L36_1 = "SI_UNIT_SKILL_DESC_S_ESPR_PILE_RA_PASSIVE_LV1"
L37_1 = "Wer süchtig nach Nervenkitzel ist, sucht immer und überall eine noch intensivere Stimulation. Erhöht Status-Effekt-WDS-Rate um 50 %."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT5_INTERLUDE3"
L38_1 = "Die Welt drängt uns immer dazu, einen Sinn in unserem Leben zu finden. Aber niemand sagt uns, dass unsere Berufung im Leben tief in uns selbst zu finden ist."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT2_INTERLUDE2"
L39_1 = "Das Valentinus-Kloster ist eine Kultreligion, die sich aus Gläubigen zusammensetzt, die die Ideologie der Gesellschaft akzeptiert haben. Sie glauben, dass die Begegnung mit einem transzendenten Wesen, das frei von den Zwängen der Realität ist und auch als See bekannt ist, sie zur Wahrheit führen wird.\nAllerdings begann sich das Blatt langsam zu wenden und das Kloster verlor seine Ziele. Die Asketen konzentrierten sich mehr auf die Mittel, um ein transzendentes Wesen bis zur Unkenntlichkeit durch Zaubersprüche zu beobachten und einzufangen."
L37_1[1] = L38_1
L37_1[2] = L39_1
