L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_WEDDING_1_PROLOGUE"
L48_1 = "Die Bürger, die die häufigen Katastrophen satt hatten, tauchen nach und nach auf. Die ersten, die den Frühling begrüßten, waren die zukünftigen Bräute und Bräutigame, die sich nach schönem Wetter sehnten."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_WEDDING_1_2"
L49_1 = "Der Veranstaltungsort ist voller entzückter Gespräche. Sehr gut. Ich werde jetzt damit beginnen, die Zerstörung der frisch vermählten Paaren zu dirigieren."
