L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_1_2"
L24_1 = "Für diejenigen, die Scham verspüren, ist Sühne die Buße, mit bloßem Auge im Dunkeln zu tappen. Und für diejenigen, die keine Scham verspüren, ist es ein Recht, sie einzufordern."
L22_1[1] = L23_1
L22_1[2] = L24_1
