L32_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_17"
L33_1 = "Ein Rahmen, der wie ein Lächeln dekoriert ist, das den Instinkt eines Jägers ausstrahlt. Rüste dies im Profil aus, um die Macht deines Unternehmens zu präsentieren."
L31_1[1] = L32_1
L31_1[2] = L33_1
