L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_2_1"
L35_1 = "Die Miliz trifft sich selten direkt mit dem Klienten. Dies ist eine Vorsichtsmaßnahme für den Fall, dass sie erwischt werden."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_5_ACT1_PROLOGUE"
L36_1 = "Die Geschichte beginnt, als eine Frau, die die Hässlichkeit der Welt satt hat, einen Jungen trifft."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_3_3"
L37_1 = "Die Friseurin fühlte sich nicht besser, als sie ihre Halskette vom Söldner zurückbekam, denn sie wurde von allen verachtet.\nDas Biest fragte sie: „Was ist deiner Meinung nach schlimmer? Jemanden zu töten oder jemand anderen zum Töten zu zwingen? Die Friseurin wollte die Antwort auf diese Frage nicht wissen."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_3_2"
L38_1 = "Der Söldner war schon lange fort, bevor ihr klar wurde, dass er die Halskette genommen hatte, die ihre Mutter ihr gegeben hatte. Nachdem sie sowohl ihre Liebe als auch ihr Vermögen verloren hatte, beschloss sie, auch das letzte, was sie hatte, wegzuwerfen.\nAn diesem Tag sprach ein Tier, das ihre Verzweiflung roch, zu ihr.\n„Warum weinst du?“ Wenn du sowieso sterben wirst, dann hilf mir lieber!"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP9_5_2_4"
L39_1 = "Der schlimmste Tag"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_1_1"
L40_1 = "Das Überlassen der Beute ist der höchste Ausdruck der Zuneigung zu einem Raubtier."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP9_5_4_4"
L41_1 = "Das Ende der Jagd"
