L18_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ESPR_CA_FROZEN_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_FROZEN_GET_01"
L19_1 = "Willkommen am Strand der Träumerei, Administrator. Haha, die Nacht hier wird wie ein Traum im Fluge vergehen, aber es wird eine gute Gelegenheit für uns sein, uns besser kennenzulernen."
L17_1[1] = L18_1
L17_1[2] = L19_1
