L19_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ESPR_CA_FROZEN_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_FROZEN_LOBBY_TOUCH_LIFETIME_2"
L20_1 = "Wie die Sterne, die am Nachthimmel hell scheinen ... waren Sie mein Leuchtfeuer, als die Zeit still stand. Jetzt ist es an mir, Ihnen zu helfen."
