L40_1 = "Doch die Menschheit wiederholt dieselben Fehler und vergräbt ihre Vergangenheit im riesigen, vergesslichen Fluss der Zeit."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_2_2"
L41_1 = "Diejenige, die Gottes Wind stiehlt und sich über die Stille lustig macht."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE5"
L42_1 = "Die unzähligen Wunden am Körper des Gottes des Jenseits waren bereits vom dunklen Gift des Gottes der Verwesung durchdrungen.\nIm Wissen, dass auch seine Seele befleckt sein würde, wenn sie nicht behandelt würde, rief der Gott des Jenseits seine drei Nachkommen zusammen."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE3"
L43_1 = "Die Siegel-Division Gordias war erforderlich, damit sich unsere Vorfahren auf der Normalside niederlassen konnten. Um die Welt zurückzuerobern, in der sie mit den Göttern koexistieren konnten, wollte die Gordias-Division an der Seite der Administration kämpfen und den Weltuntergang verhindern."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_3_4"
L44_1 = "Die Seele eines in der Leere erwachten Gottes wird ihre Wurzeln verlieren und ziellos umherwandern."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_3_EPILOGUE1"
L45_1 = "Die Nanahara-Familienallianz hat sich im Laufe der Zeit verändert. \nOb es Glück oder Unglück ist ...\nHängt von Ihrer Wahl ab."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_2"
L46_1 = "Die Lehrlinge Gottes bahnten sich ihren Weg in die Zukunft. Sie hinterließen ein Erbe namens „Heilige Schätze“, das ihre Nachkommen zum Schutz des Anwesens nutzten."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE1"
L47_1 = "Die Familienallianz entstand um die Familie Nanahara, einem Clan von Priestern, die Schlangen verehrten. Ihre Existenz war die Sühne der Menschheit für den Verrat an Gott."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_2_3"
L48_1 = "Derjenige, der sich die Ohren zuhält und sich der Disziplin widersetzt."
L46_1[1] = L47_1
L46_1[2] = L48_1
