L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_UNIT_SKILL_DESC_GEASS_MA_SEITEN_PASSIVE_LV1"
L21_1 = "Taucht auf, nachdem sie um den Einsatzort herumgeflogen ist. Geht bei Einsatz für 10 Sekunden in Perfektes ASW über. Kann Heimlichkeit-Einheiten erkennen und wird permanent immun gegen Betäubungstreffer von Spezialfähigkeiten oder niedriger."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_UNIT_TITLE_GEASS_LANCELOT"
L22_1 = "Lancelot Frontier"
