L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_SKIN_DESC_NKM_UNIT_GEASS_M_LANCELOT_LIMITED"
L9_1 = "<color=#ffd34c>※Kampfflugzeuge können nicht verändert werden.※</color>\n\nBeim Orden der schwarzen Ritter gibt es ein mysteriöses Mädchen.\nInnerhalb der Organisation kursieren zwar Gerüchte über sie, aber diese Gerüchte interessieren sie überhaupt nicht.\nAber ist es nur aus einer Laune heraus, dass sie, der alles gleichgültig ist, eine schwarze Uniform trägt?\n\n<color=#ffd34c>Weißt du, warum der Schnee weiß ist? Das liegt daran, dass du vergessen hast, welche Farbe du hast.</color>"
L7_1[1] = L8_1
L7_1[2] = L9_1
