L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_SKIN_DESC_NKM_UNIT_SECURITY_S_AGENT_PAJAMAS"
L15_1 = "Selbst eine vielbeschäftigte erstklassige Agentin braucht mal eine Pause.\nAber es ist zu schade, einen unerwarteten freien Nachmittag nur mit Schlafen zu verbringen.\nIch werde diesen freien Tag genießen, indem ich Hard Rock über meine Kopfhörer dröhnen lasse und Pfannkuchen esse, die meine Mutter gemacht hat.\n\n<color=#ffd34c>Sollen wir eine kleine Pause machen, bevor wir weiter jagen? Ich habe immerhin schon einen roten Panda gefangen, den ich so liebe.</color>"
L13_1[1] = L14_1
L13_1[2] = L15_1
