L38_1 = "SI_UNIT_SKILL_DESC_BORDER_SA_HORSE_SKILL_LV5"
L39_1 = "Curian und verbündete Warden erhalten Immunität gegen Betäubungstreffer von Ultimate-Fähigkeiten oder niedriger für 8 Sekunden nach Wirken. Erhöht außerdem 8 Sekunden lang das eigene ATMP um 10 % und den Buff-Wert um 2 % für jede verbündete Einheit auf dem Schlachtfeld, einschließlich sich selbst. (max. 10 Stapelungen / Beschwörungsanzahl und Bosse ausgenommen)"
L37_1[1] = L38_1
L37_1[2] = L39_1
