L3_1 = "SI_SKIN_DESC_NKM_UNIT_HARMONY_C_VIOLIN_SUMMER"
L4_1 = "Ein Resort mit sommerlicher Atmosphäre.\nDa kam ein wandernder Troubadour.\nFantastische Fähigkeiten und eine sensationelle Songauswahl.\nLernen Sie jetzt die Aufführungen kennen, die die Augen und Ohren der Urlauber fesselten.\n\n<color=#ffd34c>Sind Sie hier, Manager? Helfen Sie mir, die Ausrüstung aufzubauen.</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_1"
L5_1 = "Ein Requiem, das das weltweite Ende läutet.\nDiejenigen, die berührt haben, was im Namen der Rettung der Welt nicht berührt werden darf. Ihr Wille lebt in verdrehter Form weiter.\n\n<color=#ffd34c>※ Der Event-Dungeon muss mit einem NPC abgeschlossen werden.</color>"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_HARMONY_CA_CONDUCT"
L6_1 = "Ein Rahmen, der einen Dirigent beim Stimmen von Instrumenten mit prägnantem Klangbild symbolisiert. Rüste dies im Profil aus, um die Macht deines Unternehmens zu präsentieren."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_14"
L7_1 = "Ein Rahmen, der der Rüstung derer nachempfunden ist, die zur Sühne an die Front gehen. Rüste dies im Profil aus, um die Macht deines Unternehmens zu präsentieren."
L5_1[1] = L6_1
L5_1[2] = L7_1
