L46_1 = "SI_PF_TUTORIAL_TEXUTRE_SHADOW_PALACE_INFO_DESC_02"
L47_1 = "Für den Zugang zu Schattenpalästen benötigst du <COLOR=#FFBC00>Quanten-Koordisteine</COLOR>.\n<COLOR=#FFBC00>Täglich um 4 Uhr</COLOR> wird 1 Quanten-Koordistein ausgegeben.\n<COLOR=#FFBC00>Wenn du schon mehr als 7 Quanten-Koordisteine besitzt, bekommst du diesen nicht.</COLOR>"
