L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_2"
L35_1 = "Was Schatten angeht, ist die Administration nicht nur wegen der Gefahr, die sie darstellen, besonders vorsichtig. So hat sie sich beispielsweise auch noch auf keine Haltung dazu verständigt, ob Schatten so behandelt werden sollten, als wären sie ihren Counter-Originalen gleichgestellt."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_1"
L36_1 = "Die Counter-Akademie freut sich über alle jungen Counter.\n\n<color=#ff3636>Schnapp dir den Jackpot vom Himmel, um Einsatzressourcen zu erhalten.</color>\n"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP6_ACT2_INTERLUDE"
L37_1 = "Die Counter-Akademie ist deshalb so riesig, weil sie Schülerinnen und Schüler mit allen möglichen unterschiedlichen Spezialfähigkeiten unterbringen muss."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_UNIT_SKILL_DESC_S_MILITIA_SEONGTAE_PASSIVE_LV1"
L38_1 = "Erhöht den Counterabwehr-SDN-WDS um 30 % und teilt die Hälfte dieses Effekts mit umstehenden Soldaten. Auch Lee Yuri kann wie andere Soldaten von diesem Effekt profitieren."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_1_2"
L39_1 = "Die nationale Polizei leidet seit Langem unter einem Mangel an Talenten.\nIhre einfachen Mitglieder sind nicht stark genug, um die von den Countern begangenen Verbrechen zu bewältigen."
L37_1[1] = L38_1
L37_1[2] = L39_1
