L27_1 = "SI_BATTLE_MONSTER_BOSS_BASIC_MINISTRA_PV_CA_PHASE"
L28_1 = "Nutze <color=#FFBC00FF>Yoo Minas</color>Einsatzladung, um aus dem <color=#C57BF4>Schwächefeld</color> zu entkommen."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_2_DESC"
L29_1 = "Willst du die Fähigkeit eines Bedieners verbessern, kannst du <COLOR=#FFBC00>Bediener mit der gleichen Fähigkeit</COLOR> als Material verwenden. Je höher die Klasse des Materialbedieners, desto höher sind deine Chancen auf Erfolg. Wenn die Fusion fehlschlägt, verringert sich die ursprüngliche Stufe der Fähigkeit nicht, die Materialbediener verschwinden aber trotzdem."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_3_DESC"
L30_1 = "Du kannst <COLOR=#FFBC00>Bediener mit einer anderen Nebenfähigkeit</COLOR> als Material verwenden, um diese auf einen Zielbediener zu übertragen. Der Materialbediener <COLOR=#FFBC00>muss mindestens die gleiche Klasse wie der Zielbediener haben</COLOR>. <COLOR=#FFBC00>Betätige die Schaltfläche „Nebenfähigkeit ändern“,</COLOR> um die Änderung durchzuführen. Nach der Änderung <COLOR=#FFBC00>wird deine Nebenfähigkeiten-Stufe auf 1 zurückgesetzt</COLOR>."
L28_1[1] = L29_1
L28_1[2] = L30_1
