L36_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_MATCH_1_DESC"
L37_1 = "Du kannst andere Nutzer in der Liga-Liste auswählen und mit ihnen Übungskämpfe durchführen. Übungskämpfe laufen asynchron ab.\nDurch Übungskämpfe kannst du täglich eine bestimmte Anzahl an Fehdepunkten erhalten. <COLOR=#FFBC00>※ Bei Übungskämpfen mit Partnern erhältst du keine Punkte.</COLOR>"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_2_DESC_00"
L38_1 = "Im Ligakampf kannst du deinen Trupp nach dem Matching zusammenstellen.\nDu und dein Gegner <COLOR=#FFBC00>wählen abwechselnd Einheiten aus</COLOR>, um einen Trupp zu bilden.\nEs können keine <COLOR=#FFBC00>identischen Einheiten</COLOR> verwendet werden."
L36_1[1] = L37_1
L36_1[2] = L38_1
