L41_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_FACILITY_3_DESC"
L42_1 = "Im Büro des Geschäftsführers kannst du Lebenslange Verträge abschließen und Scouting betreiben. Der Zweck des Terrabrains ist aktuell noch nicht bekannt."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_NA_YUBIN@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_NA_YUBIN_LOBBY_TOUCH_NORMAL_4"
L43_1 = "Was das reine Potenzial betrifft, war Sooyeon zweifellos der beste Counter der gesamten Administration. Selbst heute ist sie noch sehr beeindruckend."
