L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_SKIN_DESC_NKM_UNIT_C_SCHOOL_CHAIR_SUMMER"
L44_1 = "Im Sommer gibt es nichts Besseres als einen Tag am Strand.\nSchau, eine Eisbärfamilie schlittert übers Eis.\nHungrige Pinguine jagen fliegenden Fischen hinterher!\nAber, ähm … warum klingt diese Robbe wie die Schulglocke?\n\n<color=#ffd34c>Hehe … ich kann unmöglich noch einen Bissen Lachssushi essen …</color>"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_1_DESC"
L45_1 = "Beim Strategiekampf kannst du dich <COLOR=#FFBC00>an nicht gleichzeitig ablaufenden Kämpfen erfreuen</COLOR>.\nDu kämpfst gegen die <COLOR=#FFBC00>Verteidigungs-Trupps anderer</COLOR>. Die <COLOR=#FFBC00>Kämpfe werden automatisch durchgeführt</COLOR>.\nBei einem Sieg erhältst du Siegespunkte. Bei einer Niederlage verlierst du sie."
L43_1[1] = L44_1
L43_1[2] = L45_1
