L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SIGMA_1_3"
L33_1 = "Die Menschheit hat Myriaden von Wesen hervorgebracht, die einer externen Kontrolle bedürfen.\nUnd niemand hat ihnen beigebracht, wie sie sich außerhalb dieser Kontrolle verhalten sollen.\n\n<color=#ffd34c>In diesem Abschnitt kämpft Terrabrain allein auf der Counterside.</color>\n<color=#ffd34c>Unterstützungsdrohnen heilen Verbündete und verwirren C. O.s, was den eingehenden Schaden verringert.</color>"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_MISSION_TITLE_ACHIEVE_RAID_HIGH_SCORE_016"
L34_1 = "Menschliche Waffe"
