L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_DP_BASE_SUB_MENU_DETAIL_PERSONNEL"
L35_1 = "Personalverwaltung ist die Basis des Erfolgs. Die Geschäftsführung, das Büro des Chefs, sorgt mit internen Bewertungen\nfür Effizient und Produktivität. Grundlage sind zwar die Standardleistungsindikatoren der Administration, aber das letzte Wort haben natürlich Sie, Herr Vorsitzender."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_1_2"
L36_1 = "Die menschliche Sprache spiegelt die menschlichen Kulturen wider."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_SKIN_DESC_NKM_UNIT_C_FALLEN_ROSARIA_SUMMER"
L37_1 = "Menschliche Emotionen sind immer ein interessantes Thema.\nBesonders an Urlaubsorten wie diesen sind sie im Überfluss verfügbar.\nDort drüben, Leute in einer Dreiecksbeziehung …\nÄhm, dunkler Fürst, was starrt Ihr denn an?\n\n<color=#ffd34c>Ich kann diese ganze Eiscreme nicht alleine essen. Auch einen Bissen?</color>"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
