L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_SKIN_DESC_NKM_UNIT_PUPPET_C_BLIND_HALLOWEEN"
L20_1 = "Kennst du die Geschichte von der neunschwänzigen Füchsin?\nIn Gestalt einer schönen Frau verführte sie Männer und stürzte ein Land ins Chaos.\nMit dieser Füchsin verhält es sich jedoch etwas anders.\nNachdem sie einen Mann verführt hat, bindet sie sich an ihn und verlangt Schmerzen von ihm.\n\n<color=#ffd34c>Warum ich Menschen verführe? Natürlich, damit sie mir Schmerzen zufügen.</color>"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_SIXWING_NA_YUBIN@AB_UI_UNIT_VOICE_NKM_UNIT_C_SIXWING_NA_YUBIN_LOBBY_CONNECT"
