L8_1 = "SI_SKIN_DESC_NKM_UNIT_C_ALT_SEO_YOON_SPRING"
L9_1 = "Von aufregenden Übertragungen zur Mittagszeit\nbis hin zum Schreiben von Drehbüchern und Filmen von Events.\nIch kann alles für dich erledigen.\nDas ist die Aufgabe einer Anführerin.\n\n<color=#ffd34c>Test, Test, kann mich jemand hören?</color>"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_3"
L10_1 = "Aus dem „Task Planet“-Artikel vom 7. März:\nAls die Unterstützung eingestellt wurde, verfiel die Ausrüstung und die Angestellten verließen das Unternehmen. Erhebliche Leistungseinbußen führten zu weiteren Budgetkürzungen.\nDie Verantwortlichen von Daymine sind immer noch besessen von der Frage, wie sie die Kosten senken können."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_2"
L11_1 = "Aus dem „Task Planet“-Artikel vom 7. März:\nTASKFORCE-Unternehmen benötigen hervorragende Unterstützung und Ausrüstung. Aber die Verantwortlichen von Daymine geizten mit ihren Investitionen und kürzten immer wieder die Budgets unter dem Vorwand der „Förderung höherer Effizienz“."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_4"
L12_1 = "Aus dem „Task Planet“-Artikel vom 7. März:\nLetztendlich gelang es Daymine nicht, bei den Raumkoordinaten, die es nach langer Zeit erlangt hatte, Eternium zu erhalten.\nDaymines Scheitern bietet viele Lehren für diejenigen, die in der nun blühenden TASKFORCE-Branche tätig sind."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_1"
L13_1 = "Aus dem „Task Planet“-Artikel vom 7. März:\n… Nach dem Großen Läuterungskrieg gehörte Daymine zu den Vorreitern in der TASKFORCE-Industrie, doch nun vermeiden sie es, in die Counterside einzutauchen, und nehmen nur noch Unterwerfungsmissionen in verderbten Gebieten an."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
