L7_1 = "Als Anführerin zwingt sie Feinde in der Umgebung, sie 6 Sekunden lang anzugreifen. Erzeugt eine Barriere mit 30 % der max. LP."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_SKIN_DESC_NKM_UNIT_C_JAPAN_SETSUNA_SUMMER"
L8_1 = "Als Oberhaupt der Familie muss ich mich stets um das richtige Auftreten bemühen,\naber das ist leichter gesagt als getan.\nManchmal will ich nur in Badesachen Spaß am Strand haben.\nIch frage mich, ob meine Schwester mich verstehen würde.\n\n<color=#ffd34c>Dieser Urlaub bleibt unser Geheimnis. Du wirst doch niemandem davon erzählen, oder?</color>"
L6_1[1] = L7_1
L6_1[2] = L8_1
