L2_1 = "SI_BOSS_DESC_08"
L3_1 = "Eine Offizierin des Replacer-Syndikats. Sie ist ein regenerierter Replacer, der als Arbiter des Terraside-Systems geschaffen wurde.\nLaut Geheimdienst der Administration handelt es sich bei ihr um ein entwickeltes Wesen, das den alten Replacer-Bishop mit nachgemachten Klippot-Faktoren kombiniert.\nSie scheint von den Erinnerungen ihrer Quelle beeinträchtigt, aber das hält sie nicht von der Erfüllung ihrer Pflichten für ihre Organisation, das feindselige Replacer-Syndikat, ab.\n\n<color=#FFCF3B>※ Der regenerierte Bishop erschafft in ihrer Ultimate-Phase vorübergehend einen unsterblichen Klon.</color>"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_BOSS_DESC_07"
L4_1 = "Eine Offizierin des Replacer-Syndikats. Sie ist ein regenerierter Replacer, der als Hüterin des Terraside-Systems geschaffen wurde.\nLaut Geheimdienst der Administration handelt es sich bei ihr um ein entwickeltes Wesen, das aus den Biodaten des Replacer Knights neu erschaffen wurde. Alles an ihr, auch Persönlichkeit und Kampffähigkeiten, soll unermesslich verbessert worden sein.\n\n<color=#FFCF3B>※ Greife den Regenerierten Knight an und entferne die Barriere, bevor diese abläuft.</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
