L38_1 = "SI_SHOP_CASH_ITEM_DESC_160550"
L39_1 = "Nur verfügbar in den ersten 30 Tagen nach deiner Registrierung!\nEin ultraeffizientes Pflichtpaket!"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_GET_01"
L40_1 = "Dieser Duft, den ich vermisst habe ... gehört zur Realität. Endlich bin ich zurück."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_CAPTAIN"
L41_1 = "Erwarten Sie bloß nicht, dass ich Ihnen gegenüber lax sein werde."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_CONNECT"
L42_1 = "Willkommen zurück. Läuft es bei der Führung reibungslos?"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_CONNECT_LIFETIME"
L43_1 = "Willkommen, Kamerad. Nun befehlen Sie mir."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_NORMAL_1"
L44_1 = "Ein Stammtisch? Nein danke. Meine Präsenz bei solchen Treffen verdirbt meiner Erfahrung nach die Stimmung."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_NORMAL_2"
L45_1 = "Ein Friede ohne Stärke ist Augenwischerei. Sagen Sie jederzeit Bescheid, wenn Sie am Kampftraining teilnehmen möchten."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_NORMAL_3"
L46_1 = "Operationslogbuch. Mein Kamerad sieht im Alltag relativ verpeilt aus. Dann muss ich mich eben doppelt anstrengen ... Hm? Nein?"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_NORMAL_4"
L47_1 = "Für die Aufrechterhaltung einer tüchtigen Organisation braucht es einen strengen Vorgesetzten. Wenn es jemand tun muss, tue ich es, das ist alles."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_LIFETIME_1"
L48_1 = "Neuerdings setze ich diese sogenannten Plastikmodelle zusammen, um meine Gedanken zu ordnen. Das macht überraschend Spaß. Ich werde Ihnen eines schenken, wenn ich richtig gut darin werde."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_LIFETIME_2"
L49_1 = "Wie die Zeit fliegt, macht einem Angst. Ich hätte es nie geglaubt, wenn jemand über die junge Sooyeon gesagt hätte, dass aus ihr mal so eine triste Erwachsene wird."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_LIFETIME_3"
L50_1 = "Operationslogbuch. Mein Kamerad erteilt keine Befehle. War meine Forderung denn zu belastend? Oder ... wird beabsichtet, dass ich nervös werde?"
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_LOBBY_TOUCH_LIFETIME_4"
L51_1 = "Ein Glück, dass mein Kamerad jemand ist, der nicht unter den Verderbniswellen leidet. Würden Sie bitte weiterhin meine Hand halten? So lange wie möglich ... Ich möchte Ihre Wärme spüren."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_C_ADMIN_ARTILLERY_WORLDMAP_CHECK"
L52_1 = "Egal, wohin ich auch gehe ... der Duft der Realität ist besinnlich."
L50_1[1] = L51_1
L50_1[2] = L52_1
