L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_YG_SORIM_RA"
L10_1 = "Die Counter-Akademie der Administration hält jedes Jahr ein Fest ab, das offen für Außengäste ist. Um das Image der Counter zu bessern, werden spektakuläre Aufführungen dargeboten, die die Fähigkeiten der Schüler verwenden.\nDas Highlight dieses Jahres ist „Absprung! Sondereinsatzteam zur Tierrettung!“ Man kann sich freuen auf ein abenteuerliches Pulverfass von einem Theaterstück, in dem der alte Hase „Abzug des Urteils“ und „Sergeant Smith“ vorkommen.\nDas Schauspiel der Hasenranger in den Hauptrollen wird tatkräftig unterstützt von den älteren Schülern mit Feuerfähigkeiten. In der Szene, in der Sergeant Smith im Kampf Kopfstand stehend stirbt, sollen sie ihr tiefes Beileid bekundet haben. "
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_UNIT_DESC_S_YG_SORIM_RA"
L11_1 = "Stetig steigendes ATMP und verbesserte Angriffe. Verwendet Ultimate-Fähigkeit für schnelle Treffer an der Frontlinie"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_ATTACK_LV1"
L12_1 = "Schießt mit dem Gewehr auf ein Ziel vorne."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_HYPER_LV1"
L13_1 = "Wirft Sergeant Smith hoch in die Luft, um bewaffnete Unterstützung zu verlangen. Verwendet ein Maschinengewehr, das gerade genau richtig eingetroffen ist. Verursacht jeweils 3-mal und insgesamt 9-mal einen Flächenschaden auf Distanzen, die 800, 1000 und 1200 entsprechen."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_HYPER_LV10"
L14_1 = "Immunität gegen SDN während Ultimate"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_HYPER_LV5"
L15_1 = "SDN +50 %"
