L14_1 = {}
L15_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_LEADER_LV1"
L16_1 = "Die Verbündeten im nahen Bereich werden immun gegen Erblindung."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_LEADER_LV5"
L17_1 = "Die Rauchgranate verschwindet nach Zündung nicht, sondern fliegt noch einmal weiter, um doppelt zu explodieren."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_PASSIVE_LV1"
L18_1 = "Überwältigt das Zielobjekt schnell und effektiv. Beim Standardangriff steigt das ATMP um 4 % und max. auf 20 %. Nach jedem 3. Standardangriff am Boden verschießt sie eine verbesserte Kugel, die 30 % mehr Schaden verursacht und die Ziele bis zu 2-mal durchdringt."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_PASSIVE_LV10"
L19_1 = "Blockiert für 2 Sekunden die Fähigkeiten der Verteidiger, die von verbesserter Munition getroffen wurden."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
