L26_1 = "Da sind Sie ja. Ich warte schon den ganzen Tag auf Sie, Liebling."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_CA_MINISTRA@AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_CA_MINISTRA_LOBBY_TOUCH_NORMAL_1"
L27_1 = "Ich war … fürchterlich töricht und dumm. Aber es heißt ja, Unwissenheit sei bisweilen ein Segen."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_CA_MINISTRA@AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_CA_MINISTRA_LOBBY_TOUCH_NORMAL_2"
L28_1 = "Angesichts der Tatsache, was für ein Miststück ich war, vermisse ich an meinem alten Leben überhaupt nichts. Und was meine herzallerliebste Schwester angeht … wäre die wohl eine Ausnahme."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_CA_MINISTRA@AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_CA_MINISTRA_LOBBY_TOUCH_NORMAL_3"
L29_1 = "Ich bemitleide die Narren, die sich an ihre lächerliche sogenannte Realität klammern. Würden sie nur ihre Menschlichkeit aufgeben, welch unglaubliche Freiheit würde sie erwarten."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
