L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_1_CM"
L3_1 = "Jehuty Biotech investierte erhebliche Anstrengungen, um sein Image zu verbessern.\nZum Beispiel wurden die unteren Stockwerke des Hauptquartiers erweitert, um Bildungseinrichtungen zu schaffen, in denen Besucher mehr über Biotechnik erfahren können."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_2_CM"
L4_1 = "Die mittleren Stockwerke des Hauptquartiers dienten als Rückgrat des Unternehmens, da viele seiner Büros die Verwaltung und das Management von Forschungseinrichtungen auf der ganzen Welt beaufsichtigten.\nAllerdings beschwerten sich Mitarbeiter auf dieser Etage oft darüber, dass der riesige Aufzug, der direkt von der U-Bahn in die obersten Stockwerke führt, zu viel Platz einnehme. "
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_3_CM"
L5_1 = "Die oberen Stockwerke des Hauptquartiers waren ein geheimer Bereich, der nur dem Vorsitzenden, den Führungskräften und ihren Sekretären zugänglich war. Nicht viele Mitarbeiter interessierten sich für diesen Bereich.\nDie oberen Stockwerke mitsamt ihrer Routinewege, Mitarbeiterhandbücher und sogar Versammlungsorte für Führungskräfte werden von allen praktischen Tätigkeiten ausgeschlossen."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
