L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_EPILOGUE"
L49_1 = "Momo sagte, ein Gebäude sei explodiert, also bin ich ihr gefolgt. Wer hätte gedacht, dass es unser Laden wäre? Ich kann Momos Gesichtsausdruck an diesem Tag nicht vergessen."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_1"
L50_1 = "Ich bin noch nicht lange hier, aber ich fühle mich, als wäre ich schon ewig hier. Natürlich weiß ich, dass das nicht ewig so bleiben kann."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_2"
L51_1 = "Ich habe mir versprochen, dass ich meine heilige Mission nicht aufgeben werde. Aber wie kommt es, dass ich immer wieder zögere? Vielleicht bin ich schon vom Teufel verführt worden."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
