L37_1 = "SI_PF_EVENT_GREMORY_BAR_MOMO_COMPLETE_ERRAND"
L38_1 = "Ich bin müde. Für mich heißt es Feierabend."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_GET_01"
L39_1 = "Knie nieder, Mensch. Ich bin Morgana Mordred, Dämonenfürst der Verzweiflung. Was?! Nicht Momo! Verkürze meinen Namen nicht so! Oh, Süßigkeiten? Für mich? Dann ernenne ich dich hiermit zu meinem dritten Himmelskönig! Fühl dich geehrt!"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_LOBBY_CAPTAIN"
L40_1 = "Ein Ort, der für einen Dämonenfürsten geeignet ist."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_LOBBY_CONNECT"
L41_1 = "Ich habe Hunger. Mach mir etwas Süßes."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_LOBBY_TOUCH_NORMAL_1"
L42_1 = "Ob meine Hörner echt sind? Was für eine Frage! ... Nun, wenn du mir nochmal etwas Süßes gibst, erlaube ich dir, sie für eine Weile zu berühren."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_LOBBY_TOUCH_NORMAL_2"
L43_1 = "Ich bin stark. Ich habe niemanden zu fürchten. Aber diese Kreatur namens Barkeeperin ist etwas schwer zu zähmen. Himmelskönig, geh zu ihr und nimm ihr die Süßigkeiten weg!"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_LOBBY_TOUCH_NORMAL_3"
L44_1 = "Das ist kein Drachen-Stofftier! Huff Puff ist ein alter Freund von mir. Oho, du siehst schon richtig verängstigt aus, wo ich nur von ihm spreche. Hab ruhig Angst vor ihm."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_OPR_MOMO@AB_UI_UNIT_VOICE_OPR_MOMO_LOBBY_TOUCH_NORMAL_4"
