L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_INTRO_ORIGINAL"
L8_1 = "Je höher das Ideal, desto leichter fällt es, und je reiner das Herz, desto leichter wird es beschmutzt. Trotzdem ... habe ich nicht die Absicht, meine Liebe jetzt noch aufzugeben."
