L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_CONNECT_LIFETIME"
L10_1 = "Der Grund, warum ein Schmetterling seine Flügel in die weite Welt ausbreiten kann, ist die Liebe. Selbst wenn er dabei zu hoch hinauffliegt und sich seine Flügel verbrennt, wird er glücklich sein, wenn er es einem Geliebten zuliebe tut."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_ALPHA_CA_JIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_1"
L11_1 = "Sagen Sie nur Bescheid, Boss. Was auch immer Ihr Wunsch ist, erfülle ich ihn gerne. Auch wenn es mich alles kostet."
