L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_ACT4_INTERLUDE_1"
L3_1 = "Wenn Sie sich zuerst an uns wenden würden, wären wir Ihnen sehr dankbar, Professor."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_ACT4_INTERLUDE_2"
L4_1 = "Listige Magier, vulgäre Vampire und gefräßige Lykanthropen. Brennen, brennen, alle werden verbrennen. In den Flammen der Tyrannin des Nordens."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_1"
L5_1 = "Der Barde hinterließ Ratschläge, die für einen Drink geeignet waren.\nVermeide jeglichen Kontakt zu Fremden im Central Palace."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_2"
L6_1 = "Ein Individuum, das einem Sklaven Schaden zufügt, ist mit jemandem vergleichbar, der das Eigentum anderer beschädigt."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_3"
L7_1 = "Der Sieg kann nicht ohne die Anwesenheit eines passenden Gegners gefeiert werden."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_4"
L8_1 = "Die Krone musste standhaft sein. Die Bedrohung durch den Dämonenfürsten war nicht mehr nur eine Geschichte, die Kindern erzählt wurde."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_1"
L9_1 = "Es ist immer schwierig, talentierte Personen zu finden, die sowohl kompetent als auch vertrauenswürdig sind."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_2"
L10_1 = "Eine Organisation, die ihr Zentrum verliert, wird zusammenbrechen."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_3"
L11_1 = "Vielleicht sind Sie jetzt mit dem Namen der „Gesellschaft“ vertraut. Allerdings trug sie in der Vergangenheit möglicherweise einen viel bizarreren Namen. Wie wäre es mit Lemuria?"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_4"
L12_1 = "Die Öffentlichkeit ist immer noch neugierig, wie diejenigen, die während des Großen Läuterungskrieges erschienen und verschwanden, den Sieg erringen konnten. Nun, alle bis auf eine Person.\nFür sie war Maria Antonov die natürliche Heldin."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_1"
L13_1 = "Es werden Waffen benötigt, um zu kämpfen."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_2"
L14_1 = "Wenn Menschen in die Enge getrieben werden, hoffen sie auf ein Wunder."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_3"
L15_1 = "Die Schattenpaläste sind ein Raum, der die Klippa-Dimension und die Normalside verbindet. Je stärker der Einfluss der Klippa-Dimension ist, desto größer ist die Gefahr."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_4"
L16_1 = "Eine Imitation aus einer Handvoll Resten, die mit Faden zusammengenäht und mit dem Evangelium gefüllt sind."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_4_1"
L17_1 = "Erhebt eure Waffen und bleibt in Formation. Das Imperium wird hoch auf den aufgestapelten Leichen unserer Gegner stehen."
