L7_1 = {}
L8_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_NIGHTMARE_3_1"
L9_1 = "Ist es ein Traum?"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_NIGHTMARE_3_1_HM"
L10_1 = "Alter Albtraum"
L8_1[1] = L9_1
