L4_1 = "Die Leute haben in der Regel mehr Albträume im Hochsommer. Haben Sie ... einen schlechten Traum gehabt?"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_CONNECT_LIFETIME"
