L5_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_1"
L6_1 = "Kaltes Wasser und ein eisiger Albtraum. Ganz schöne Kombination. Vielleicht schwimme ich deshalb auch gerne, oder nicht?"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_2"
L7_1 = "Das ist das erste Mal ... Ich war so beschäftigt, Albträume loszuwerden, dass ich gar nicht gemerkt habe, wie ich meine Füße eingetaucht habe. Es ist in Ordnung, sich ein bisschen zu entspannen, oder?"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_3"
L8_1 = "Gibt es etwas Hoffnungsloseres als das Spiegelbild des Mondes auf dem Wasser? Man versucht, daran festzuhalten, und es fließt dahin. So schade ... aber ich versuche es immer wieder, obwohl ich weiß, dass es nicht geht."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_4"
L9_1 = "Diese Flamme wird nicht ausgehen, selbst wenn sie nass wird. Es ist nämlich ein Albtraum, der den Träumer immer wieder störte. Deshalb lasse ich ihn immer hoch am Himmel. So kann er ein kleines Stück des Himmels erhellen, wie ein Stern."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_SUMMER@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_LIFETIME_1"
L10_1 = "Träume sind wie Wasser. Es fühlt sich an, als würde man frei herumschwimmen. Aber ... genau wie im Wasser spürt man diesen erstickenden Druck. Ich empfehle es also nicht wirklich."
L8_1[1] = L9_1
L8_1[2] = L10_1
