L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_UNIT_SKILL_DESC_REAPER_C_ARMS_ATTACK_LV1"
L50_1 = "Fügt Gegnern vor sich Schaden zu, indem sie mit einem mechanischen Arm zugreift. Wenn sie während einer Bewegung oder während eines Standardangriffs von einem Standardangriff getroffen wird, wird 1 x [Täuschung] verbraucht, um einen Gegenangriff auszuführen, der die Barriere entfernt und Gegner zurückstößt."
