L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_SKIN_DESC_NKM_UNIT_CANARY_S_SHIELD_HALLOWEEN"
L39_1 = "Hallo, meine Lieben! Dieses Match ist ein Event-Match für unsere lieben Champions vom Canary-Trupp!\nAch du lieber Gott?! Das Mädchen, das sonst nur langweilige Outfits trug, erschien in einem wirklich schwindelerregenden Outfit!!!\nDas könnte dazu führen, dass einige Fans, zur Polizei gehen müssen!\nDie Zähne dieses mürrischen Chihuahuas werden euch zerfleischen, also seid besser vorsichtig.☆\n\n<color=#ffd34c>Süßes oder Saures. Wenn Sie nicht gleich das Macaron rausrücken, beiß ich Sie noch.</color>"
L37_1[1] = L38_1
L37_1[2] = L39_1
