L41_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_EMBLEM_BIRTHDAY"
L42_1 = "Ein von Mitarbeitern heimlich vorbereiteter Kuchen, um Ihren Geburtstag zu feiern.\nJeder hat etwas Geld gegeben, um ihn ganz nach seinen Wünschen zubereiten zu lassen. Wer am meisten gezahlt hat, bleibt Ihrer Fantasie überlassen."
L40_1[1] = L41_1
L40_1[2] = L42_1
