L42_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_PACKAGE_BIRTHDAY_BOX"
L43_1 = "Eine Kiste voller Glückwünsche zum Geburtstag.\nWenn du sie öffnest, kannst du verschiedenste Geschenke erhalten."
