L49_1 = "REACTOR_DESC_1201"
L50_1 = "Eine Kugel aus Seelen. Lässt einen Sturm der Bestrafung über diejenigen wüten, die von Begierde erfüllt sind. Der Reaktor spiegelt die Wut über den Verlust eines geliebten Menschen als Medium zur Leistungssteigerung wider."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "REACTOR_DESC_1223"
L51_1 = "Ein Handbuch des Untersuchungsrats, das verschiedene Gegenmaßnahmen zusammenfasst. Es ist sehr dick, da selbst für kleine Situationen detaillierte Lösungen angegeben sind. Der Reaktor spiegelt den Glauben als Medium zur Leistungssteigerung wider."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "REACTOR_DESC_1256"
L52_1 = "Eine Waffe voller göttlicher Erhabenheit, geschmiedet mit unzähligen Wünschen. Nachdem der ursprüngliche Besitzer starb, führt der Schöpfer des Schwertes es an seiner Stelle. Der Reaktor spiegelt den Willen, auf Gebete zu antworten, als Medium zur Leistungssteigerung wider."
L50_1[1] = L51_1
L50_1[2] = L52_1
