L6_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_GET_01"
L7_1 = "Ich bin Luna und ab heute Ihr persönliches Hausmädchen! Hehe, ich bin ein wirklich kompetentes Hausmädchen. Ich kann putzen, die Wäsche waschen, Hausarbeiten erledigen, Sie unterhalten und vieles mehr!"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_CAPTAIN"
L8_1 = "Das habe ich mir verdient! Das beste Hausmädchen sollte so behandelt werden."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_CONNECT"
L9_1 = "Meister! Ich habe Ihnen schwarzen Tee – Argh! Oh nein ... Ich habe alles verschüttet ..."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_CONNECT_LIFETIME"
L10_1 = "Oh, Sie sind zurück, Meister. Lassen Sie mich Ihre Jacke nehmen. Sind Sie müde? Wollen Sie eine Fußmassage? Sagen Sie, was immer Sie sich wünschen."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_NORMAL_1"
L11_1 = "Aua! Oh nein! Dies ist die Vase, die Meister mag! Autsch! Auuu! Hör auf, mich zu schlagen, du böse Katze!"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_NORMAL_2"
L12_1 = "Boss! Oh, Sie sind ja jetzt mein Meister. Sie wollten Lunas besonderen Burger probieren, oder? Ach, kommen Sie schon, probieren Sie ihn einfach! Sobald Sie diesen Burger probiert haben, können Sie nie etwas Anderes essen!"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_NORMAL_3"
L13_1 = "Ich habe letzte Nacht Trompete geübt, um für Sie zu spielen, aber ich habe eine Lärmbeschwerde erhalten! Puh ... ich kann dies nicht tun, ich kann jenes nicht tun, ich werde einfach aufhören, Hausmädchen zu sein!"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_NORMAL_4"
L14_1 = "Willkommen, Meister. Ähm, ehrlich gesagt ... gab es ein großes Feuer in der Küche, als ich Ihr Essen zubereitete. Wäre also stattdessen ein Burger in Ordnung? Hä? Glauben Sie, ich habe es getan, weil ich nur Burger essen wollte?"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_LIFETIME_1"
L15_1 = "Aua! Autsch! Hilfe, Meister! Dieses Kätzchen schlägt ständig auf mich ein! Oh, denken Sie, so drücken Katzen ihre Liebe aus? Dann ist es wohl auch in Ordnung, wenn ich Sie schlage! Was? Sie wollen das?"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_LIFETIME_2"
L16_1 = "Meister! Lassen Sie uns ein Spiel spielen! Das „Gegenseitig Füttern“-Spiel! Wir füttern uns abwechselnd mit Burgern und Pommes! Hehehe. Ich habe gehört, dass andere Hausmädchen so mit ihren Meistern spielen."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_LIFETIME_3"
L17_1 = "Meister! Wohin gehen Sie denn jetzt schon wieder?! Es wäre besser, ein einsames Hausmädchen nicht zu vernachlässigen! Heute bleiben Sie hier! Ich werde eine beruhigende Melodie spielen!"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_MAID@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_C_TRUMPET_LOBBY_TOUCH_LIFETIME_4"
L18_1 = "Puh ... Es ist wirklich hart, Hausmädchen zu sein ... Ich glaube, ich werde auch heute wieder vor Erschöpfung zusammenbrechen. Sie erlauben mir, meinen Kopf auf Ihren Schoß zu legen ...? Aber dann wären unsere Rollen vertauscht. Aber einen Tag lang darf ich mir das sicher gönnen."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
