L30_1 = "SI_EPISODE_DESC_1_SS_PRYDWEN"
L31_1 = [[
A threat no one could foresee that occurred in the aftermath of the Qliphoth Game.
A man on the verge of greatness and the man who carries on the legend. The Society and the Institution's age-old destiny reach a new phase.]]
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_GET_01"
L32_1 = "The name's Burnett. Roy Burnett of Prydwen Institution. Now, I'll be helping you out as an Institution agent. So, let's try to get along while I'm here."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_CAPTAIN"
L33_1 = "An escort mission? Leave it to me."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_CONNECT"
L34_1 = "I was cleaning up the office a bit. Don't mind me, it's just my hobby."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_CONNECT_LIFETIME"
L35_1 = "Morning coffee's the best. When I was at the Institution, a certain someone kept making me drink black tea."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_TOUCH_NORMAL_1"
L36_1 = "I heard this suit was what my grandfather used to wear when he was in the Old Administration. I don't know if I'm fit to be wearing this, but... you know. It's up to me to decide from now on, right?"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
