L32_1 = {}
L33_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_2_DESC"
L34_1 = "Jedes Mitglied des Konsortiums erhält 5 Zugänge zu jeder Läuterungsmission.\n<COLOR=#FFBC00>Jedes Mal, wenn du die Arena abschließt, erhöht sich die Läuterungsrate um die Anzahl der verdienten Medaillen.</COLOR> Wenn die Läuterungsrate 100 % erreicht, erhältst du ein Artefakt."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_3_TITLE_DESC"
L35_1 = "Jedes Mitglied des Konsortiums erhält 5 Zugänge zu jeder Läuterungsmission.\nDu kannst <COLOR=#FFBC00>Artefakte aus der Arena kombinieren,</COLOR> um deinen Trupp zu stärken, bevor du dich dem Raid anschließt.\nDer Boss der Läuterungsmission erhält je nach seiner Berserkerstufe mehr LP, ANG und VER."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_PF_EVENTMATCH_MAIN_MENU_RULE_PLAY_RULE_AUTO"
L36_1 = "Regeln\n\n– Manuelle Steuerung nicht möglich\n– Feste Einsatzreihenfolge\n– Verbannungen & Vorteile nicht angewandt\n– Ausrüstungswerte werden angewandt"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_BOSS_DESC_S2_03"
L37_1 = "Der Anführer einer neuen religiösen Gruppe, von der angenommen wird, dass sie sich von Eckharts Gesellschaft für supranaturale Forschung abgespalten hat.\nEr führt eine Gruppe selbsternannter Verräter an und greift wahllos geheime Quarantäneeinrichtungen an verschiedenen Orten an, um Teile des Sees zu bergen. Dafür wird er weltweit gesucht.\nEr nutzt eine unbekannte Art von Energie und man muss sich besonders vor seinen Fesseln in Acht nehmen."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_UNIT_NAME_DELTA_CA_JAKE_CONTEST_SKILL_TROPHY"
L38_1 = "Das würde der Oberst nie tun"
