L22_1[2] = L24_1
L23_1 = {}
L24_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_1"
L25_1 = "Diese Stille mag ich zwar, aber manchmal vermisse ich den Klang der Musik. ... Du willst für mich ein Saiteninstrument lernen? Es ist bewundernswert, dass du diese Entscheidung getroffen hast, aber achte darauf, dass du dir nicht die Finger verletzt."
L23_1[1] = L24_1
