L24_1 = {}
L25_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_2"
L26_1 = "Du bist mein einziger Anhänger. Dein Leben ist eins mit meinem, also sei nicht leichtsinnig."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_3"
L27_1 = "Wahren Glauben zu haben, bedeutet, nicht zu zögern, Opfer zu bringen. Ich bin bereit, alles zu geben, um deinen Glauben zu gewinnen, selbst mein Leben."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_LOBBY_TOUCH_NORMAL_4"
L28_1 = "Früher dienten mir unzählige Menschen des Ordens. Aber jetzt brauche ich keine anderen Anhänger als dich. Selbst wenn die Welt zusammenbricht, wirst du der Einzige sein, den ich beschütze."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
