L2_1 = {}
L3_1 = "SI_SHOP_TOP_BANNER_TAB_EVENT_BG_CLB_001"
L4_1 = "Du kannst den Hintergrund des Guilty Gear-Zusammenarbeit-Event kaufen."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_UNIT_SKILL_DESC_GUILTY_C_SOL_PASSIVE_LV1_ver2"
L5_1 = "Nach jedem 5. Angriff kann er seine aktuelle Aktion unterbrechen und etwas anderes tun. Dies zwingt umstehende Einheiten, ihn anzugreifen und verringert für 6 Sekunden ihr ATMP um 30 %. (Die Anzahl der Angriffe wird auch nach erneutem Einsetzen weiter gezählt.) Im PvE erhöhen sich ANG und Fähigkeitentempo pro Guilty Gear-Einheit auf dem Schlachtfeld um 3 % (maximal 18 %)."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_UNIT_SKILL_DESC_GUILTY_C_SOL_SKILL_LV1_ver2"
L6_1 = "Schlägt die Feinde vor ihm mit der Faust und verursacht Flächenschaden. Steigert SDN-Dezimierung für 8 Sekunden nach Fähigkeitsanwendung um 30 %."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_UNIT_SKILL_DESC_GUILTY_S_MILLIA_PASSIVE_LV1_ver2"
L7_1 = "Bei 70 % oder niedrigeren LP stößt sie umliegende Ziele von sich weg und lässt sie durch die Luft fliegen. Betäubt Ziele, auch wenn sie sich im Spezialfähigkeitsmodus befinden, und steigert Fähigkeitentempo für 6 Sekunden um 30 % pro Ziel (maximal 90 %). Für 2 Sekunden nach dem Passiv ist sie immun gegen Schaden. Im PvE erhöhen sich ANG und Fähigkeitentempo pro Guilty Gear-Einheit auf dem Schlachtfeld um 3 % (maximal 18 %)."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_GUILTY_C_RAMLETHAL_PASSIVE_LV1_ver2"
L8_1 = "Der Standardangriff nach Erarlumo löst je nach Entfernung zum Gegner bis zu 3 verbesserte Angriffe aus. Der Angriff mit der geringsten Entfernung besitzt 70 % der Kraft von Erarlumo. Angriffsreichweite und Kraft erhöhen sich pro Stufe um 50 %. Im PvE erhöhen sich ANG und Fähigkeitentempo pro Guilty Gear-Einheit auf dem Schlachtfeld um 3 % (maximal 18 %)."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_UNIT_SKILL_DESC_GUILTY_C_RAMLETHAL_SKILL_LV1_ver2"
L9_1 = "Löst einen mächtigen Angriff mit hohem ANG-Wert aus, der Flächenschaden nach vorne anrichtet. Nach Fähigkeitsanwendung wird der Cooldown der Spezialfähigkeiten zurückgesetzt und sie wirkt 3 Sekunden lang Perfektes ASW. Nach der Zurücksetzung des Cooldowns ignorieren ihre Spezialfähigkeiten Schaden durch Betäubungstreffer, die innerhalb von 15 Sekunden nicht von Angriffen mit Ultimate-Fähigkeiten herrühren, und verursachen Flächenschaden vorne. Auf diese Weise aktivierte Spezialfähigkeiten setzen den Cooldown nicht zurück und sie wirkt nach Fähigkeitsanwendung 6 Sekunden lang Perfektes ASW."
L7_1[1] = L8_1
L7_1[2] = L9_1
