L2_1 = "SI_PF_EPISODE_EVENT_INFO_FRONTBAY_TEXT"
L3_1 = [[
Die <color=#ffcf3b>Kopfgeld-Marken</color>,
die man mit der Event-Episode [Verlasse das Schiff] erhalten kann,
lassen sich gegen diverse Produkte eintauschen.]]
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_PF_DEFENCE_BANNER_01_DESC_1"
L4_1 = "Wie du weißt, ist das Meer vor Front Bay nie ruhig, da Piraten ständig gegeneinander kämpfen. Seefahrer sind dazu bestimmt, trotz allem in die weite See zu stechen.\nKapitän, es ist Zeit, den Anker zu lichten und die Segel zu setzen! Wegen der Schwarzen Flut werden die diesjährigen C. O.s ein großer Fang! Was auch immer uns in die Quere kommt, ob Wellen oder Menschen, lasst uns unsere Namen auf dem Wasser verewigen! Wir hinterlassen vielleicht Meeresschaum, aber wir werden niemals etwas bereuen!"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EVENT_TAB_DESC_EVENT_EPISODE_FRONTBAY"
L5_1 = "Verlasse das Schiff"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_ITEM_MISC_NAME_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_28"
L6_1 = "Rahmen: Romantische Freibeuterin"
L4_1[1] = L5_1
L4_1[2] = L6_1
