L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_28"
L10_1 = "Ein Rahmen, der dem süßen Outfit der romantischen ersten Schützin nachempfunden ist. Rüste dies im Profil aus, um die Macht deines Unternehmens zu präsentieren."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_EPISODE_EVENT_FRONTBAY"
L11_1 = "Eine von der Administration ausgestellte Marke, die gegen Credits eingetauscht werden kann. Sie gilt auch als Ablassbrief, weshalb die gesuchten Kriminellen von Front Bay ihr Leben im Kampf gegen C. O.s riskieren, um eine zu bekommen.\nWird nach Ende des Events gelöscht."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_BG_FRONTBAY"
L12_1 = "Das massive Bollwerk, das den inneren und äußeren Hafen von Front Bay trennt. Es wurde errichtet, um als Schutzschild vor der Schwarzen Flut des Kraken zu dienen."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_EMBLEM_SPECIAL_EVENT_EPISODE_FRONTBAY"
L13_1 = "Eine Truhe, die der Große Pirat überall auf der Insel versteckt hat.\nSie wird als Schatztruhe bezeichnet, enthält jedoch nur die Habseligkeiten des Großen Piraten anstelle von Gold und Silber."
L11_1[1] = L12_1
L11_1[2] = L13_1
