L9_1 = "Erhalte alle Normal-Medaillen für [1-1. Nemesis of the Sea]"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_GET_01"
L10_1 = "It has been a long time since I had felt the weight of this sword. My methods might have changed, but my determination to serve you has not changed, Master."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_CAPTAIN"
L11_1 = "Gordias Division Deputy Commander, Hayami Sanae. I accept the orders."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_CONNECT"
L12_1 = "Welcome, Master."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_CONNECT_LIFETIME"
L13_1 = "Please come in, Master. I will bring you some tea."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_TOUCH_NORMAL_1"
L14_1 = "Although my swordsmanship may not match my predecessors, I will serve you with all I have. So, trust and leave it to me, as you always have."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_TOUCH_NORMAL_2"
L15_1 = "Ever since I've had more free time these days, I've been enjoying various weekend activities. Playing the cello at a cozy jazz bar has become a small joy of life, and it's all thanks to your consideration, Master."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_TOUCH_NORMAL_3"
L16_1 = "A swordsman must swing one's sword as if it is an extension of one's body. Since I am your sword, do not hesitate to use me, Master."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_TOUCH_NORMAL_4"
L17_1 = "My clan was able to clear our name and punish the evil doers thanks to you, Master. So please do not feel uncomfortable for my volunteering to serve you."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_TOUCH_LIFETIME_1"
L18_1 = "Commander Nao used to sharpen weapons by spewing fire out from her mouth. I tried to imitate her once, and accidentally swallowed the alcohol and ended up getting drunk. But it was all when I was immature and young."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR@AB_UI_UNIT_VOICE_NKM_UNIT_JAPAN_C_CHIHIRO_PR_LOBBY_TOUCH_LIFETIME_2"
L19_1 = "I obtained two tickets to a movie premiere. If it is okay with you, would you allow me to borrow your time, Master? No, samurais do not appear in this movie... It is a romance film."
L17_1[1] = L18_1
L17_1[2] = L19_1
