L37_1 = "Durchbruch erfordert <COLOR=#FFBC00>Credits</COLOR> und <COLOR=#FFBC00>EIG-Kerne</COLOR>.\nJe höher die Klasse der Einheit, desto mehr EIG-Kerne, SEIG-Kerne und Credits werden benötigt."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC_VER3"
L38_1 = "Mitarbeiter können auf Kosten von Fusionskernen, Fusionskernfragmenten oder S-Fusionskernen<COLOR=#FFBC00> fusioniert (Limitfusion)</COLOR> werden.\n<COLOR=#FFBC00>Limitfusion</COLOR> erhöht bei jeder Ausführung die <COLOR=#FFBC00>max. Stufe um 2</COLOR> und die <COLOR=#FFBC00>Werte-Wachstumsrate um 2 %</COLOR>.\n<COLOR=#FFBC00>Limitfusion</COLOR> kann <COLOR=#FFBC00>bis zu 10-mal</COLOR> durchgeführt werden."
L36_1[1] = L37_1
L36_1[2] = L38_1
