L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_GET_01"
L35_1 = "Your causal calculator must have finally permitted my cooperation. I am Felix, the Northern Union's Chief of the General Staff. But you can address me by name when it's just us two. And I'll call you Boss."
