L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_CONNECT"
