L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_1"
L39_1 = "Death is followed by rest. We have a responsibility to restore order among the suffering Shadows. However, we must also respect their unwavering loyalty even after death. Like my Shadows, and the Shadow that you care for."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
