L41_1 = "Have you ever held the hand of a dying soldier? The sight of a cold, trembling hand clinging so desperately... is something one cannot forget in mere days. It's quite effective when you need to straighten your mind."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
