L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_CONNECT_LIFETIME"
L19_1 = "Hello, Squire. Good morning, is it not?"
