L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_1"
L20_1 = "One must show confidence in order to earn trust from others. That's why I'm learning a lot from Ms. Aura. Like her lines that leave a strong impression... or even her cool poses."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_2"
L21_1 = "I have a lot of flaws. I'm a pushover and can't really refuse anything. But I guess that helps me gain courage when I'm around Ms. Aura."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_3"
L22_1 = "Ms. Aura likes to lay on the grass and appreciate the night sky. It's romantic, but... whenever I imagine all the bugs crawling all over me... Eww..."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_4"
L23_1 = "I'm from an aristocratic family. People from other countries tend to sneer for mentioning nobility in the 21st century, but... I don't mind. Ms. Aura said that the spirit it contains is more important than its symbolic meaning."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
