L24_1 = "Uh... The way that I talked when I first met you? Well... I got inspired by books about knights that Ms. Aura recommended, and had this urge to leave a stunning impression... Could you please forget I ever did that?"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
