L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_UNIT_SKILL_DESC_ACADEMY_CA_TWINTAIL_HYPER_LV1"
L36_1 = "Beschwört eine versteckte riesige Waffe und wendet sich in die Richtung, in der sich mehr Feinde in Sichtweite befinden, um dort Flächenschaden zu verursachen. Erstellt einen Bereich mit Erlittener SDN-Potenzierung +20 % vorn für 15 Sekunden."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_UNIT_SKILL_DESC_ACADEMY_CA_TWINTAIL_HYPER_LV5"
L37_1 = "Erlittene SDN-Potenzierung im Bereich nun +40 %"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_UNIT_SKILL_NAME_ACADEMY_CA_TWINTAIL_PASSIVE"
L38_1 = "Beste Elite"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_UNIT_SKILL_DESC_ACADEMY_CA_TWINTAIL_PASSIVE_LV1"
L39_1 = "Wird dauerhaft immun gegen die Betäubungstreffer von Spezialfähigkeiten oder niedriger. Bei einem Einsatz erhöht sich die SDN-Dezimierung 14 Sekunden lang um 30 %. Wechselt für 4 Sekunden in den Zustand der Eisernen Verteidigung, wenn 18 Mal getroffen wurde (max. 10 Mal nach Einsatz). Im Zustand der Eisernen Verteidigung werden Treffer nicht gezählt. Führt nach Aktivierung der Spezialfähigkeit einen verbesserten Angriff aus, der Flächenschaden vorne verursacht und bis zu 3 getroffene Ziele 3 Sekunden lang fesselt◇."
L37_1[1] = L38_1
