L2_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_GET_01"
L3_1 = "Hey there, it's your maid. Oops, is this not how it's done? Lily's got you covered as your trusty bodyguard, Master."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_CAPTAIN"
L4_1 = "I'll guard you perfectly, Master, without any trouble."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_CONNECT"
L5_1 = "Have you been waiting long, Master? I got a bit delayed while sprucing myself up."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_CONNECT_LIFETIME"
L6_1 = "I've been waiting for you here all along, Master. Will you take my hand?"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_NORMAL_1"
L7_1 = "Even though I'm attending this masquerade as your partner, my duty remains guarding you, Master. No one will lay so much as a finger on you."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_NORMAL_2"
L8_1 = "Telling me to taste a slice of the cake first... Were you trying to check for poison? Relax, it's sweet and tasty, so you can dig in without concern."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_NORMAL_3"
L9_1 = "Oh, the tranquilizer? I made sure it's dressed up in a color perfect for tonight's ball. But... fingers crossed we won't need it."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_NORMAL_4"
L10_1 = "Are you talking about my dress? The Chief Maid went all out and designed it HERSELF. Seeing it now, I truly realize how impressive you, whom the Chief Maid serves, are, Master."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_LIFETIME_1"
L11_1 = "You're wondering if it's tough to serve you, Master? Nope. Being able to admire your awesomeness right by your side makes me feel that Lady Luck is on my side."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_LIFETIME_2"
L12_1 = "Couldn't take your eyes off me, huh? It's part of a maid's duty to present herself in a way that befits her master. Still... it makes me happy to hear you say I'm beautiful."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_LIFETIME_3"
L13_1 = "My eyes are darting around to ensure there are no dangerous items near you. It's... definitely not because I'm curious or anything."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_LOBBY_TOUCH_LIFETIME_4"
L14_1 = "Stick right by my side. With so many people around, there's no telling who could pose a threat. It would also help if we locked arms to seem closer together."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_WORLDMAP_CHECK"
L15_1 = "If that is your command, Master..."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_WORLDMAP_MISSION_START"
L16_1 = "Shall we enjoy the masquerade?"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_MAID_C_MASK_NEWYEAR2025@AB_UI_UNIT_VOICE_NKM_UNIT_MAID_C_MASK_WORLDMAP_MISSION_COMPLETE"
L17_1 = "We had so much fun, so how about a drink?"
