L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA_LOBBY_CONNECT"
L36_1 = "*Sniff* Something smells delicious... Oh! It's you, Client? I was just looking for traces of evil spirits."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA_LOBBY_CONNECT_LIFETIME"
L37_1 = "Hmph...! Oh, you're here, Client. W-what I'm hiding behind me? It's definitely not the handkerchief you left behind! Oops... I just said it, didn't I?"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA_LOBBY_TOUCH_NORMAL_1"
L38_1 = "There was a time when I forced myself to drink grape juice, pretending it was blood. I used to drink so much during mass that I often got scolded..."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA_LOBBY_TOUCH_NORMAL_2"
L39_1 = "When I first saw Junk food, I thought she was a trial sent by the Lord. That delicious smell... If the forbidden fruit truly existed, wouldn't it have smelled just like her?"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_GOETIA_LOBBY_TOUCH_NORMAL_3"
L40_1 = "This outfit? I designed it myself. Regular nun robes get shredded in no time when handling C.O.s summoned from Goetia."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
