L11_1[2] = L13_1
L12_1 = {}
L13_1 = "REACTOR_DESC_1271"
L14_1 = "Ein königlicher Schatz, den der Weise des Stumpfs über lange Zeit gehütet hat. Er wurde ursprünglich für den Körperbau eines erwachsenen Mannes geschaffen, doch mit genug Kraft kann selbst ein junges Mädchen ihn führen. Der Reaktor spiegelt, Ausdauer und Verantwortungsbewusstsein – jene Tugenden, die das Schicksal zu überwinden vermögen, als Medium zur Leistungssteigerung wider."
