L35_1 = "SI_UNIT_SKILL_DESC_ZODIAC_CA_CHARLOTTE_ATTACK_LV1"
L36_1 = "Fügt einmaligen Schaden nach vorne zu. Nach der Reaktivierung der Passiven Fähigkeit oder dem Einsatz der Ultimate-Fähigkeit führt jeder darauffolgende Standardangriff zusätzlich einen verbesserten Angriff aus. Der verbesserte Angriff verursacht Festen Flächenschaden nach vorne (2 Wirksame Treffer)."
L34_1[1] = L35_1
L34_1[2] = L36_1
