L37_1 = "Gnade von Astraea"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_UNIT_SKILL_DESC_ZODIAC_CA_CHARLOTTE_PASSIVE_LV1"
L38_1 = "Der Schaden aller Angriffe erhöht sich proportional zur den max. LP. Der Einsatz in einem Kampf ist auf 1 Mal begrenzt. Fallen die LP auf 1 % oder niedriger, wird eine Ultimate-Flächenfähigkeit nach vorne ausgelöst, und sie erleidet für 4 Sekunden keinen Schaden. Während dieser Zeit können keine Standardangriffe oder Fähigkeiten eingesetzt werden, und Effekte zur Erhöhung oder Verringerung des ATMP haben keinen Einfluss. Nach Ablauf der Dauer werden die verbleibenden LP auf 50 % des maximalen Werts gesetzt und der Kampf wird fortgesetzt."
L36_1[1] = L37_1
L36_1[2] = L38_1
