L15_1 = "SI_EPISODE_DESC_1_SS_PRIDE"
L16_1 = [[
Ritter irren umher, jeder mit seinem eigenen Stolz.
Zwei Gerechtigkeiten, die lange Zeit nebeneinander bestanden, beginnen nun zu kollidieren.]]
L14_1[1] = L15_1
