L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_PROLOGUE"
L17_1 = "Wir zogen das Schwert für die Ehre – doch die Welt wollte es nicht.\nWofür also sollen wir kämpfen?"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_PRIDE_1_1"
L18_1 = "Winterabend bei Sonnenuntergang"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_1_1"
L19_1 = "Wohin führt der Lebensweg? Was gleicht ihm wohl? Auch wenn sich zufällig Spuren im Schnee verlieren – wenn sie verwehen, wie ließe sich Ost und West noch unterscheiden? Manche starben schon und wurden zu neuen Türmen, und wo Mauern einst standen, blieb keine Spur der Vergangenheit. Erinnerst du dich noch an jenen beschwerlichen Pfad? Die Weg war lang, die Menschen erschöpft, und selbst die Maultiere klagten in der Dunkelheit."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE1"
L20_1 = "Die Sternenritter der vorherigen Generation galten als die glänzende Goldene Generation.\nDoch als ihr Ruhm verblasste und ihre Erinnerungen zu wehmütiger Nostalgie wurden, legten sie einer nach dem anderen die Schwerter nieder."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_PRIDE_1_2"
L21_1 = "Gebrochene Gerechtigkeit"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_1_2"
L22_1 = "Gemeinsam besiegen wir den Feind.\nAls ich allein war, spürte ich meine Ohnmacht."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE2"
L23_1 = "Erinnerst du dich an unser Gelöbnis? Das Versprechen jenes Tages, geschlossen unter den erhabenen Sternen. Es war unser Lebenswegweiser und innigster Herzenswunsch zugleich."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE3"
L24_1 = "Der ehemalige Ritter-Captain war einer der stärksten Sternenritter aller Zeiten, doch seine Schwäche war offensichtlich:\nSein einziger Blutverwandter."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE4"
L25_1 = "Ein Clown ohne Maske. Auf dem ungeschminkten Gesicht sieht man nur Trauer."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE5"
L26_1 = "Auch wenn er die richtige Antwort kennt, kann er sie nicht geben. Das macht ihn selbst elend."
L24_1[1] = L25_1
L24_1[2] = L26_1
