L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE24"
L49_1 = "Was der frühere Ritter-Captain dem Orden hinterließ,\nwar nicht das Jungfrauenschwert, sondern der Stolz eines Chevaliers."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE25"
L50_1 = "Gemeinsam mit den Schauspielern hebt sich endlich der Vorhang der Bühne."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE26"
L51_1 = "Weil es ihr an Talent fehlte, musste sie ein anderes Schild als das geweihte führen.\nWas einst eine beschämende Wahrheit war, wurde im Moment, als sie ihre Kameraden vor den C.°O.s rettete, zu tiefem Stolz."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_PRIDE_5_1"
L52_1 = "Konfliktausbruch"
