L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LIFETIME_COMPLETE"
L38_1 = "Hesitating with half-baked resolve will only lead the world to ruin. I'll let these blades prove that the justice we pursue is the one true path."
