L6_1 = "SI_UNIT_SKILL_DESC_ADMIN_CA_CLOUD_PASSIVE_LV1"
L7_1 = "Wird permanent immun gegen die Betäubungstreffer von Spezialfähigkeiten oder niedriger. Nach 5 Treffern erhöht sich der Schaden von verbesserten Angriffen um 25 % (bis zu 100 %). Alle 8 Sekunden wird automatisch ein verbesserter Angriff ausgeführt, der festen Flächenschaden nach vorne verursacht. Nach dem Einsatz eines verbesserten Angriffs wird der erhöhte Schaden zurückgesetzt und eine Barriere erzeugt, die 10 Sekunden lang 30 % der max. LP absorbiert."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_ADMIN_CA_CLOUD_PASSIVE_LV5"
L8_1 = "Immunität gegen Erhöhung des Fähigkeiten-Cooldowns. Nach dem Einsatz eines verbesserten Angriffs wird der Angriff permanent um 20 % erhöht (max. 8 Stapelungen)."
L6_1[1] = L7_1
L6_1[2] = L8_1
