L9_1 = "SI_UNIT_SKILL_DESC_ADMIN_CA_CLOUD_SKILL_LV1"
L10_1 = "Erzeugt ein Feld vorne. Innerhalb des Feldes ist sie gegen Betäubung◇ immun und gewährt sich selbst sowie verbündeten Verteidigern und Vorhutkämpfern 30 % SDN-Dezimierung (nicht entfernbar). Gegner im Feld erleiden bei einem Treffer durch Yeonhwa zusätzlichen Schaden als Äquivalent zu Spezialfähigkeiten. Stirbt Yeonhwa, verschwinden alle verbleibenden Felder auf dem Schlachtfeld."
L8_1[1] = L9_1
L8_1[2] = L10_1
