L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_SKILL_DESC_OPR_LEEJISOO"
L26_1 = "Gewährt <color=#ffd34c>allen gegnerischen Verteidigern und Vorhutkämpfern</color> für <color=#ffd34c>{time} Sekunden</color> <color=#ffd34c>Buff-Annulierung (außer bei Bossen)</color> und erhöht <color=#ffd34c>Erlittene SDN-Potenzierung um {factor1} %</color>. <color=#ffd34c>Verdoppelt</color> Dauer und Erlittene SDN-Potenzierung, wenn die <color=#ffd34c>Kosten der Ziele höher als 5</color> sind. Dieser Effekt <color=#ffd34c>kann nicht aufgehoben werden</color>."
