L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_PROLOGUE1"
L30_1 = "Ich habe nie darüber nachgedacht, ob es gut oder schlecht ist, die Vergangenheit zu vergessen und weiterzuleben. Ich erinnere mich nur daran, dass es meine eigene Entscheidung war."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_1"
L31_1 = "Ein Albtraum, der aus der Tiefe emporsteigt und wiederaufersteht. Das fließende Blut der Bestien ..."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_1_1"
L32_1 = "Schwarzer Regen"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_1"
L33_1 = "Katastrophen sind für alle schrecklich – nicht nur für die, die dabei umgekommen sind, sondern auch für die, die dabei zurückbleiben."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_1_2"
L34_1 = "Überlebender Counter"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_2"
L35_1 = "Ein Albtraum, der sich jeden Tag wiederholt. Wann werde ich wohl erwachen?"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_2"
L36_1 = "Mitarbeiter, die die Administration verlassen, durchlaufen ein Verfahren, bei dem alle Erinnerungen an ihre Zeit dort gelöscht werden. Angesichts der möglichen Folgen dieser Erinnerungen ist dies eine Maßnahme, die sowohl der Administration als auch der betreffenden Person dient."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_1_3"
L37_1 = "Katastrophenforscher"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_3"
L38_1 = "So wie es Gifte gibt, die Menschen heilen, wird auch die Verderbnis, wenn man sie erforscht, eines Tages nützlich sein. Doch Gift bleibt dennoch Gift."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_3"
L39_1 = "Das Verbergen der Augen ist ein Symbol der Geheimnisvollheit. Masken, Augenklappen und Pony gehören dazu."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_1_4"
L40_1 = "Nur im Notfall verwenden"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_4"
L41_1 = "Große Kraft hat ihren Preis. Auch wenn es Unterschiede im Ausmaß gibt, gibt es keine Ausnahmen."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_4"
L42_1 = "Sie durchschneidet den Raum mit ihrem Schwert. Je nach Fähigkeit kann sie nicht nur Gegner zerschneiden, sondern auch Gegenstände verstecken und Menschen transportieren."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_5"
L43_1 = "Die Administration entwickelte nach dem Großen Säuberungskrieg Strategien zur Wiederaufbau einer verwüsteten Welt. Viele Menschen kooperierten mit der Administration, getrieben von der einzigen Hoffnung."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT2_INTERLUDE_1"
L44_1 = "Man kann die Vergangenheit vergessen, aber nicht vor ihr davonlaufen."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_2_1"
L45_1 = "Begegnung mit der Vergangenheit"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_2_1"
L46_1 = "In den Brunnen hinab – zu deiner Zeit, die ich unbewusst verlor."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT2_INTERLUDE_2"
L47_1 = "Wie ein Tiger, der über Hügel springt, so durchschreiten sie die Zeiten. Um zu verhindern, dass diese Existenz das Heute erreicht, hat die Administration einen genialen Gelehrten angeworben – vom Schicksal dazu bestimmt."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_2_2"
L48_1 = "Verrat"
