L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_2_2"
L49_1 = "Zahlreiche Schritte, die sich durchs Dickicht schlagen auf der Suche nach Beute."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT2_INTERLUDE_3"
L50_1 = "Diejenigen, die an der Vergangenheit gefesselt leben. Und diejenigen, die sie zurückholen wollen."
L48_1[1] = L49_1
L48_1[2] = L50_1
