L2_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_2_4"
L3_1 = "Als ich meine Heimat verließ"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_2_4"
L4_1 = "Wenn man die Albträume jener Zeit erneut mit Blut in Erinnerung ruft."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT3_INTERLUDE_1"
L5_1 = "In den Erinnerungen, die ich beim Abschied vergessen musste – war da denn wirklich kein einziger schöner Moment?"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_3_1"
L6_1 = "Spindelstrauch"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_3_1"
L7_1 = "Zwischen dem Heute und der alten Zeit liegt ein besonderes Ufer, das die Grenze zwischen beiden zieht. Die Sondereinheit der Drei-Heere-Garnison erkannte an der Anzahl der Früchte des Spindelstrauchs dort, ob die Ankunft des Tigers bevorstand."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT3_INTERLUDE_2"
L8_1 = "So wie der Tiger durch die Zeit schreitet, wird auch der Mensch, in dessen Adern sein Blut fließt, jene Kraft erlangen. Auch wenn dafür ein Preis gezahlt werden muss."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT3_INTERLUDE_3"
L9_1 = "Ich habe das Rauchen von meinem Meister gelernt und es schließlich aufgegeben, doch seither überkommt mich immer wieder das Verlangen nach etwas Süßem."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_3_2"
L10_1 = "Strudelspuren"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_3_2"
L11_1 = "Ein Traum, in den man tief versinkt, lässt sich nicht mehr von der Wirklichkeit unterscheiden – nicht, bevor man erkennt, dass man ihn nicht beeinflussen kann."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT3_INTERLUDE_4"
L12_1 = "In der Hoffnung, dass es unser Schicksal verändert."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_4_1"
L13_1 = "Perlmutt-Panzer"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_4_1"
L14_1 = "Der geniale Wissenschaftler der Administration erkannte früh die Verbindung von Technik und Magie und errichtete eine Barriere, die mit seinem Blut zum Himmel gezeichnet wurde, damit der Tiger nicht bis in die Gegenwart gelangt."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT4_INTERLUDE_1"
L15_1 = "Das Herz dessen, der all die langen Jahre nichts vergessen hat und nur zusieht, ist eine sich immer wiederholende Tragödie."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP14_4_2"
L16_1 = "Tigerhügel"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_4_2"
L17_1 = "Ein Tiger, der die Seele eines Menschen verschlingt, wird von deren tiefsten Groll durchdrungen."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT4_INTERLUDE_2"
L18_1 = "Selbst angesichts eines unvermeidlichen Endes gibt es jene, die nicht zusammenbrechen, sondern voranschreiten. Auch wenn die Hoffnung am Ende dieses Weges nur eine Täuschung sein mag."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT4_INTERLUDE_3"
L19_1 = "Je größer das Biest, desto mehr ist sein Instinkt darauf ausgerichtet, Größeres zu verschlingen."
