L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_CONNECT_LIFETIME"
L12_1 = "I've been wai– Ah, sorry. I was nibbling on some dried persimmons."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_NORMAL_1"
L13_1 = "I once copied everything my master did, thinking it was cool. Even tried a cigarette, not knowing better. I still get the urge when I run out of sweets. They say withdrawal's no joke and it's true."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_NORMAL_2"
L14_1 = "The Trivanguard was built to fight the Beasts, but we also train for human opponents. One of us losing control of the Dragon Blood... would mean raising our blade against a comrade."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_NORMAL_3"
L15_1 = "I packed this lunchbox for today. Haha, of course, it's just for one person. I've got to eat enough to survive Master's afternoon drills. If you like these side dishes, I can make you one too."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_NORMAL_4"
L16_1 = "Crunchy persimmons, semi-soft ones, soft ones, and ripe ones. They're all delicious, but nothing beats dried persimmons. They're the sweetest and linger the longest. Want one?"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_LIFETIME_1"
L17_1 = "I had a dream so sorrowful I woke up in tears, but I couldn't remember why. I know I saw someone, but I don't remember the face, and only that ache remains... Have you ever had a dream like that?"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_LIFETIME_2"
L18_1 = "If life had a flavor, don't you think it'd be astringent like a persimmon? The longer it hangs and ripens, the sweeter it gets, slowly covering up that sharp bite. Kind of like how life works, isn't it? Haha, I can be surprisingly poetic when I try."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_LIFETIME_3"
L19_1 = "There's always a trace of sadness in your eyes when you look at me. Haha, what could I do to ease it? It's a shame. I wish I could understand even a little of what's on your mind."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_TOUCH_LIFETIME_4"
L20_1 = "Let's go on a picnic, while the weather's nice. If we can't hold onto this blue sky forever, then we should enjoy it while we can. Haha. This time, I packed a lunchbox for you too, Administrator. And of course, I brought dried persimmons."
L18_1[1] = L19_1
L18_1[2] = L20_1
