L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_UNIT_SKILL_DESC_FENRIR_CA_INTERN_PASSIVE_LV1"
L47_1 = "Solange sie sich auf dem Schlachtfeld befindet, können alle Verbündeten Heimlichkeit aufspüren (nicht entfernbar). Nach beliebiger Fähigkeitsnutzung führt sie für 5 Sekunden einen verbesserten Angriff auf Gegner in Reichweite aus, der Einzelschaden verursacht. Der verbesserte Angriff kann bis zu 3 Ziele treffen. Kann in Fehden gegnerischen Schiffen keinen Schaden zufügen."
L45_1[1] = L46_1
