L36_1 = "SI_UNIT_SKILL_DESC_ALPHA_C_CHESS_ATTACK_LV1"
L37_1 = "Bewegt den schwarzen Bauer als Eröffnung und verursacht Einzelschaden am Gegner. Wird die Schachfigur in ein Rook verwandelt, wird der Cooldown der Spezialfähigkeit zurückgesetzt."
L35_1[1] = L36_1
L35_1[2] = L37_1
