L37_1 = "SI_UNIT_SKILL_DESC_ALPHA_C_CHESS_PASSIVE_LV1_ver4"
L38_1 = "10 % Chance, die Schachfigur in ein Rook zu verwandeln. Befindet sich eine verbündete Schwarze Rose auf dem Schlachtfeld, beträgt die Chance 30 %. Befindet sich ein Gegner mit Perfektem ASW auf dem Schlachtfeld, beträgt die Chance 60 %. Die Wahrscheinlichkeiten werden nicht addiert; es gilt stets die höchste zutreffende Chance."
L36_1[1] = L37_1
L36_1[2] = L38_1
