L38_1 = "SI_UNIT_SKILL_DESC_ALPHA_C_CHESS_PASSIVE_LV5"
L39_1 = "Immunität gegen Betäubungstreffer von Spezialfähigkeiten oder niedriger für 8 s, wenn die Schachfigur in einen Rook geändert wird"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_UNIT_SKILL_DESC_ALPHA_C_CHESS_SKILL_LV1_ver2"
L40_1 = "Opfert beschworene Schachfiguren, um Flächenschaden um das Ziel herum zu verursachen. Das vom ersten Treffer getroffene Ziel erhält 8 Sekunden lang -24 % Fähigkeitentempo und -30 % ANG. Wenn die Schachfigur in einen Rook geändert wird, reduziert sich das Ultimate-Cooldown um 11 Sekunden."
L38_1[1] = L39_1
L38_1[2] = L40_1
