L44_1 = {}
L45_1 = "SI_DP_KEYWORD_DESC_UNIT_PUPPET_C_WHIP_PASSIVE"
L46_1 = "Erhöht für 4 Sekunden ANG um +1 % und Erlittene SDN-Dezimierung +0,5 %.\nBei max. Stapelung wird ein zusätzlicher Buff aktiviert: Ausgehende SDN-Potenzierung +15 %, der nicht aufgehoben werden kann."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_UNIT_SKILL_DESC_PUPPET_C_WHIP_ATTACK_LV1"
L47_1 = "Schlägt mit einer Peitsche im vorderen Bereich zu, verursacht Flächenschaden. Beim letzten Treffer erhält jede getroffene verbündete Einheit 1 Stapelung [#UNIT_PUPPET_C_WHIP_PASSIVE#] (max. 40 Stapelungen). Nach 4 Angriffen wird ein verbesserter Angriff ausgelöst, der den Schaden um 50 % erhöht und das Spezialfähigkeits-Cooldown wird pro getroffenen Einheit um je 1 Sekunde reduziert."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_UNIT_SKILL_DESC_PUPPET_C_WHIP_PASSIVE_LV1"
L48_1 = "Wird immun gegen Schlaf. Befinden sich verbündete Einheiten (Beschworene ausgenommen) vorne, greift sie die Verbündeten an. Alle Angriffe verursachen bei Verbündeten Schaden in Höhe von 1 % des Standardangriffs und fügen beschworenen gegnerischen Einheiten zusätzlichen Schaden in Höhe von bis zu 33 % der max. LP zu."
L46_1[1] = L47_1
L46_1[2] = L48_1
