L48_1 = {}
L49_1 = "SI_SKILL_DESC_OPR_NATALIA"
L50_1 = "Erhöht den KRIT-SDN von <color=#ffd34c>allen verbündeten Scharfschützen und Rangern</color> für <color=#ffd34c>16 Sekunden</color> um <color=#ffd34c>+{value1} %</color>. <color=#ffd34c>Dieser Effekt lässt sich nicht aufheben</color>.\n[#UNIT_OPR_NATALIA_SUMMON#] bewegt sich nach vorn in die Nähe des verbündeten Schiffs und fügt dem Ziel sowie Gegnern in der Umgebung <color=#ffd34c>Ultimate-Flächenschaden</color> zu, bevor sie sich zurückzieht (Wirksame Treffer: 4; in Fehden erleiden Schiffe keinen Schaden). Gegner, die vom letzten Treffer getroffen werden, können <color=#ffd34c>8 Sekunden</color> lang <color=#ffd34c>nicht ausweichen ◇</color>."
L48_1[1] = L49_1
