L31_1 = "Signal ignorieren"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EXPLORE_EVENT_MAIN_DESC_12"
L32_1 = "Kurz bevor der Dimensionssturm einsetzt, wurden zwei schwache Signale erfasst. Bevor du diesen Ort verlässt, solltest du zumindest eines davon überprüfen."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_RANDOM_3"
L33_1 = "Bewegendes Signal verfolgen"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_RANDOM_4"
L34_1 = "Stationäres Signal verfolgen"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EXPLORE_EVENT_MAIN_DESC_13"
L35_1 = "Mitten in der Counterside entdeckt ihr ein Spiegelfragment. In dem makellosen, durchsichtigen Spiegel spiegeln sich all die Dinge, nach denen du gesucht hast. Plötzlich überkommt dich der Drang, deine Hand danach auszustrecken."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_ALL_UNIT_GET_1"
L36_1 = "Hand nach der sich bewegenden Silhouette ausstrecken"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_ALL_ARTIFACT_GET_1"
L37_1 = "Hand nach dem glänzenden Gegenstand ausstrecken"
L35_1[1] = L36_1
L35_1[2] = L37_1
