L37_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_SKIP_2"
L38_1 = "Ingnorieren"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EXPLORE_EVENT_MAIN_DESC_14"
L39_1 = "Kaum hast du die dimensionale Route verlassen, trifft ein ohrenbetäubender Schlag das Schiff. Da tauchen Piraten mit einem Bergungsschiff auf und nehmen euch ins Ziel. Entkommen ist möglich, doch jemand anders befindet sich bereits in ähnlicher Lage. "
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_BATTLE_1"
L40_1 = "Zusammenschließen und gegen die Piraten kämpfen"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_OTHER_1"
L41_1 = "Fliehen"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EXPLORE_EVENT_MAIN_DESC_15"
L42_1 = "Während das Schiff gewartet wurde, empfangt ihr ein Artefakt-Signal. Da greift euch ein C. O. an. Je näher es kommt, desto stärker wird das Artefakt-Signal. Du begreifst bald, was das zu bedeuten hat."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_BATTLE_2"
L43_1 = "C. O. besiegen und Beute bergen"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_OTHER_2"
L44_1 = "Wartung beenden und verschwinden"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EXPLORE_EVENT_MAIN_DESC_16"
L45_1 = "Als du vom Dimensionssturm erfasst wirst, zeigen sich drei Landschaften gleichzeitig – ein temporäres Überlappen verschiedener Raumzeit-Punkte. Ist es Schicksal, das dich hierherführt? Wählst du die richtige Koordinate, kannst du auf dem Schlachtfeld Verbündete treffen, die dir zur Seite stehen."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_RANDOM_5"
L46_1 = "Dem Zufall überlassen und weiter gehen"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EXPLORE_EVENT_MAIN_DESC_17"
L47_1 = "Ihr entdeckt eine Erkundungsstation, doch es scheint, als hätten Scavenger sie bereits durchsucht. Die noch zurück gebliebenen zerstreuen sich augenblicklich, als sie euch bemerken, und setzen die beiden Schiffe in Bewegung."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_STORM_1"
L48_1 = "Dem gestohlenen Hilfsschiff folgen"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_STORM_2"
