L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EXPLORE_EVENT_MAIN_DESC_18"
L50_1 = "Du triffst auf freundliche Piraten. Ihrem Namen gerecht werdend, entschieden sie sich für eine kluge Lösung: Verhandeln statt Angreifen oder Fliehen."
L48_1[1] = L49_1
L48_1[2] = L50_1
