L2_1 = "SI_UNIT_SKILL_DESC_KNIGHT_C_EMPEROR_PASSIVE_LV1_ver2"
L3_1 = "Erhöht ANG um 2 % bis zu 40 % proportional zur Anzahl der Gegner, die durch den letzten Angriff des Standardangriffs Schaden erleiden (nicht entfernbar), und verbraucht alle Stapelungen nach dem Wirken einer Spezialfähigkeit, wenn die Stapelungen der passiven Fähigkeit ihr Maximum erreichen. Erhöht außerdem die Fernkampf-SDN-WDS um 30 %."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_UNIT_SKILL_DESC_GAMECIRCLE_C_STAR_PASSIVE_LV1_ver2"
L4_1 = "Alle 7 Standardangriffe mit ihren verbesserten Besen – ich meine, die verbesserten Elementarwaffen – führen einen verbesserten Angriff aus. Getroffene Gegner werden 4 Sekunden lang mit [#UNIT_GAMECIRCLE_C_STAR_PASSIVE#] belegt. Danach geht die Waffe kaputt und sie erhält permanent ATMP +10 % (max. 3 Stapelungen). Ihre Elementarwaffe wechselt in der Reihenfolge Blitz > Eis > Flamme > Blitz."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_UNIT_SKILL_DESC_GAMECIRCLE_C_STAR_PASSIVE_LV5"
L5_1 = "ASW pro verlorenen LP +60 %, Fähigkeitentempo +30 %"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
