L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_ITEM_DESC_IQI_EQUIP_SIXWING_CA_ACTOR_DEFENCE"
L23_1 = "Das schneeweiße Bühnenkostüm, auf das die Schauspielerin besteht, die als Aushängeschild von Charade angesehen wird. Zwar ist es recht freizügig, doch auf der Bühne zeigt der makellos weiße Schwan keinerlei Scham."
L21_1[1] = L22_1
L21_1[2] = L23_1
