L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_ITEM_DESC_IQI_EQUIP_SIXWING_CA_ACTOR_ACC_B"
L27_1 = "Eine Kabinettkarte mit einer verblassten Fotografie. Das Lächeln des Mädchens auf dem Bild ist zugleich der Moment, den sie am meisten bereut, aber auch eine Spur der Nostalgie, der sie eines Tages unweigerlich begegnen wird."
L25_1[1] = L26_1
L25_1[2] = L27_1
