L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SWANSONG_1_2_HM"
L29_1 = "O du Unglückseliger, achtlos in die Welt geworfen.\nO du Armer, der nicht voranschreiten kann und stattdessen Nachahmung und Ernte endlos wiederholt.\nIhr werdet uns unausweichlich fremd bleiben."
L27_1[1] = L28_1
L27_1[2] = L29_1
