L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_UNIT_SKILL_DESC_SECURITY_CA_SERGEANT_PASSIVE_LV1"
L31_1 = "Fügt bei einem Einsatz durch ihr Hochtempomanöver allen Gegnern mit einer Schockwelle Schaden zu. Wenn sie auf dem Schlachtfeld ist, wird der erlittene Schaden der Gegner um 15 % erhöht. Jedes Mal, wenn eine Einheit das Schlachtfeld verlässt, wird der Cooldown ihrer Ultimate-Fähigkeit um 2 s und der Cooldown ihrer Spezialfähigkeit um 1 s verringert. Wenn sie als Anführereinheit eingesetzt wird, werden Einsatzkosten in Höhe von 1 erstattet."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_UNIT_SKILL_DESC_SECURITY_CA_SERGEANT_SKILL_LV1"
L32_1 = "Entfesselt durch ihr Hochtempomanöver eine Schockwelle, die Flächenschaden verursacht, und sie wird bei Bewegung immun gegen Schaden. Ein getroffenes Ziel kann für 10 s nicht ausweichen◇."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
