L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_9"
L38_1 = "Der See des Wissens muss eins werden."
L36_1[1] = L37_1
L36_1[2] = L38_1
