L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_6_1_3"
L47_1 = "Nach dem Tod des offiziellen Counters übertrug Senior das Amt auf seine Nachfolgerin. Sie hatte gehofft, sie würde die Pflicht weiterführen, die ein geliebter Mensch hinterlassen hatte. Doch die Nachfolgerin entschied sich für die Rache. Trotzdem tadelte die Administration sie nicht und jagte sie auch nicht fort. Denn unabhängig vom Auslöser war wen auch immer sie jagte, zugleich ein Feind der Administration."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_6_INTERLUDE4"
L48_1 = "Wir sehen nur, was wir sehen wollen. Und selbst wenn dahinter etwas lauert, das den Alltag bedroht, kümmern wir uns kaum darum, im Glauben, dass es heute noch nicht unser Leben berühren wird."
L46_1[1] = L47_1
L46_1[2] = L48_1
