L35_1 = "SI_UNIT_SKILL_NAME_G1_C_TAOIST_PASSIVE"
L36_1 = "Verwandlungskunst der Geisterflamme"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_UNIT_SKILL_DESC_G1_C_TAOIST_PASSIVE_LV1"
L37_1 = "Sinken die eigenen LP auf 30 % oder weniger, erleidet der Anwender kurzzeitig keinen Schaden, fügt Gegnern vor sich Flächenschaden zu und kehrt zum Ausgangspunkt zurück. Verringert beim Wirken einer Spezialfähigkeit den Ultimate-Cooldown um 30 Sekunden."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_UNIT_SKILL_DESC_G1_C_TAOIST_PASSIVE_LV5"
L38_1 = "Für jede gegnerische Unterstützer-Einheit auf dem Schlachtfeld erhöht sich das eigene Fähigkeitentempo um +15 % (max. +45 %, nicht entfernbar)."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
