L22_1 = "AB_UI_UNIT_VOICE_OPR_SYSOP@AB_UI_UNIT_VOICE_OPR_SYSOP_LOBBY_TOUCH_LIFETIME_2"
L23_1 = "Ich glaube, dass man die Kleiderordnung nicht so ignorieren sollte. Es ist schließlich ein Unternehmen. Aber das Kind mit den langen Haaren und dem unnötig großen Umhang, das im Unternehmen herumläuft, scheint das nicht zu verstehen."
L21_1[1] = L22_1
L21_1[2] = L23_1
