L23_1 = "AB_UI_UNIT_VOICE_OPR_SYSOP@AB_UI_UNIT_VOICE_OPR_SYSOP_LOBBY_TOUCH_LIFETIME_3"
L24_1 = "Du birgst unzählige Risiken, Vater. Ich glaube nicht, dass es klug ist, diese Kriminellen rücksichtslos zu befehlen, aber ... ich kann mich um unerwartete Variablen kümmern."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "AB_UI_UNIT_VOICE_OPR_SYSOP@AB_UI_UNIT_VOICE_OPR_SYSOP_LOBBY_TOUCH_LIFETIME_4"
L25_1 = "Das kürzlich an die Börse gebrachte Munitionsunternehmen in Charade verzeichnet ein enormes Wachstum. Beobachtungsergebnisse deuten darauf hin, dass du davon profitieren könntest, wenn du in das Unternehmen investierst. Hm, ich habe was Dummes gesagt. Du bist nicht jemand, der solche geringfügigen Gewinne anstrebt."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "AB_UI_UNIT_VOICE_OPR_SYSOP@AB_UI_UNIT_VOICE_OPR_SYSOP_SQUAD_ENTER_LIFETIME"
L26_1 = "Bestätigt. Mach, was du willst."
