L31_1 = "AB_UI_UNIT_VOICE_OPR_MITCH@AB_UI_UNIT_VOICE_OPR_MITCH_LOBBY_TOUCH_LIFETIME_3"
L32_1 = "Boss, haben Sie jemals darüber nachgedacht, Streamer zu werden? Ich wette, der Chat wird Sie lieben, weil Sie so attraktiv sind! Hehe. Wenn Sie jemals einer werden, müssen Sie als Gast in meinen Stream kommen, okay?"
L30_1[1] = L31_1
L30_1[2] = L32_1
