L33_1 = "Ah, you've come. Let's make it a good one today."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_OPR_DOGABI@AB_UI_UNIT_VOICE_OPR_DOGABI_LOBBY_TOUCH_LIFETIME_1"
L34_1 = "Never once have I forgotten how to swing a sword. I've just been waiting for a reason to do so again. If you want, I can still slice down a few reeds that block your path."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_OPR_DOGABI@AB_UI_UNIT_VOICE_OPR_DOGABI_LOBBY_TOUCH_LIFETIME_2"
L35_1 = "If you've got worries, don't hold back. I'll listen, but just spare me the romance tales. I've lived a long, long time, but I've never known what it's like to love a woman in earnest."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_OPR_DOGABI@AB_UI_UNIT_VOICE_OPR_DOGABI_LOBBY_TOUCH_LIFETIME_3"
L36_1 = "The Three Blades... What a name that brings me back. Back then, I lived for the pride of it all. Hmm... If I have one regret, it's never telling that woman of the Three Blades how I felt. Well I guess that's fate too."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
