L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_SKILL_DESC_OPR_CREW"
L21_1 = "Verleiht <color=#ffd34c>allen verbündeten Einheiten</color> für <color=#ffd34c>{time} Sekunden</color> <color=#ffd34c>+{factor1} % auf {stat1}</color>. Solange der Buff aktiv ist, erhalten <color=#ffd34c>verbündete Vorhutkämpfer</color> [#UNIT_OPR_CREW_STRIKER#] und <color=#ffd34c>verbündete Verteidiger</color> [#UNIT_OPR_CREW_DEFENDER#]. Dieser Effekt <color=#ffd34c>kann nicht aufgehoben werden</color>."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_DP_KEYWORD_NAME_UNIT_OPR_CREW_STRIKER"
L22_1 = "Unbeugsames Herz"
