L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_DP_KEYWORD_DESC_UNIT_OPR_CREW_STRIKER"
L23_1 = "Gewährt Zustand der Eisernen Verteidigung, der nach 4 Treffern aufgehoben wird. Solange Eiserne Verteidigung aktiv ist, besteht Immunität gegen Betäubungstreffer von Spezialfähigkeiten oder niedriger."
L21_1[1] = L22_1
L21_1[2] = L23_1
