L14_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_LOBBY_TOUCH_LIFETIME_1"
L15_1 = "Life of an elegant lady? Dull, tedious, and full of pretense. Still, I don't regret it. It lets me savor the catharsis of battle even more."
L13_1[1] = L14_1
L13_1[2] = L15_1
