L15_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_LOBBY_TOUCH_LIFETIME_2"
L16_1 = "Since I laid down my sword, the only blade I've held is this kitchen knife. Fufu... But don't think that means you can challenge me lightly. A true master never blames her tools."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_LOBBY_TOUCH_LIFETIME_3"
L17_1 = "Pirates these days? I admire that they still chase romance... but they lack the edge we had. Heh, if I were still active, I'd whip that spirit back into shape."
L15_1[1] = L16_1
L15_1[2] = L17_1
