L17_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_LOBBY_TOUCH_LIFETIME_4"
L18_1 = "Cooking was always one of my favorite pastimes, even during my pirate days. Fufu... Judging by that look, you're curious about my cooking. Wait here a moment. I'll prepare a feast you won't forget."
L16_1[1] = L17_1
L16_1[2] = L18_1
