L18_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_SQUAD_ENTER_LIFETIME"
L19_1 = "May you achieve the world we once dreamed of twenty years ago."
