L18_1 = {}
L19_1 = "SI_SKIN_TITLE_NKM_UNIT_FENRIR_CA_HILDE_PR_GAUNTLET"
L20_1 = "Hwatu-Dealerin"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_SKIN_DESC_NKM_UNIT_FENRIR_CA_HILDE_PR_GAUNTLET"
L21_1 = "Ihnen fehlt der Nervenkitzel im gewöhnlichen Alltag?\nJetzt wartet im Casino eine ganz besondere Dealerin auf Sie.\nSie ist zwar etwas empfindlich, leicht reizbar … und manchmal bringt sie selbst die grundlegendsten Regeln durcheinander …\nDoch eines ist sicher: Sie gibt sich größte Mühe, um Ihnen ein unvergessliches Erlebnis zu bereiten.\n\n<color=#ffd34c>„Shoe …? Washing …? Solche Begriffe kenne ich nicht. Hier, nehmen Sie lieber ein paar Hwatu-Karten. Das ist mein Fachgebiet.“</color>"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_ITEM_NAME_IQI_EQUIP_ADMIN_CA_CAT_WEAPON"
L22_1 = "Bestienklaue"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_ITEM_DESC_IQI_EQUIP_ADMIN_CA_CAT_WEAPON"
L23_1 = "Eine Spezialausrüstung, die sich nur vom König der Yaksha bändigen lässt. Allein der Wille und die Entschlossenheit, die eigenen Gefährten zu schützen, vermögen die Klauen des Löwen zu entfesseln."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_ITEM_NAME_IQI_EQUIP_ADMIN_CA_CAT_DEFENCE"
L24_1 = "Pushpaka Vimana"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_ITEM_DESC_IQI_EQUIP_ADMIN_CA_CAT_DEFENCE"
L25_1 = "Eine strategische Uniform, entwickelt, um sich einen Schritt, eine einzige Sekunde schneller zu bewegen – um alle zu retten. Sie besitzt eine hohe Widerstandsfähigkeit gegenüber den Belastungen, die bei Dimensionssprüngen entstehen."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_ITEM_NAME_IQI_EQUIP_ADMIN_CA_CAT_ACC_A"
L26_1 = "Astra-Antrieb"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_ITEM_DESC_IQI_EQUIP_ADMIN_CA_CAT_ACC_A"
L27_1 = "Ein Gerät, das das Avesta-Laufwerk miniaturisiert. Ein System, das Verderbniswellen absorbiert und in Antrieb umwandelt. Für den menschlichen Körper eigentlich ungeeignet, doch der Wille, andere zu retten, hat diese Grenze überwunden."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
