L28_1 = "Hauskatze"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_ITEM_DESC_IQI_EQUIP_ADMIN_CA_CAT_ACC_B"
L29_1 = "Ein Band, das einer streunenden Katze umgebunden wurde, als Zeichen, dass sie nun eine Familie hat. Es trägt den Wunsch in sich, dass sie schnell nach Hause findet, sollte sie sich einmal verirren."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
