L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_YAKSHA_1_2_HM"
L31_1 = "Irgendwo jenseits von hier, solange auch nur ein Funken Möglichkeit verbleibt,\nwerden wir den Weg nach vorn wählen, statt stehen zu bleiben."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_UNIT_SKILL_DESC_ROOT_CA_HUNTRESS_PASSIVE_LV5"
L32_1 = "KRIT-SDN +30 %, Vorhutkämpferabwehr-SDN +40 %"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_UNIT_SKILL_DESC_ROOT_CA_HUNTRESS_SKILL_LV1"
L33_1 = "Zielt mit Licht auf das Ziel und fügt Flächenschaden am und um das Ziel zu. Getroffene Vorhutkämpfer werden für 6 Sekunden gefesselt◇."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_UNIT_SKILL_DESC_DELTA_CA_JAKE_PASSIVE_LV1"
L34_1 = "Bei einem Einsatz erzeugt er 6 Sek. lang ein Kälteschlaffeld, das den ANG von Mech-Einheiten um 30 % und ihre LP um 3 % pro Sekunde verringert (nicht entfernbar, Bosse ausgenommen). Nach jedem 3. Standardangriff fügt er Mech-Einheiten Flächenschaden zu, betäubt◇ sie 2 Sek. lang und erzeugt ein weiteres Kälteschlaffeld. Bei jeder Erzeugung eines Kälteschlaffelds wird für 1 Sekunde Eiserne Verteidigung◇ gewährt."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_UNIT_SKILL_DESC_KNIGHT_C_FLAG_PASSIVE_LV1"
L35_1 = "Steckt beim Einsatz die Familienflagge auf die eigene Position, um Gegnern Schaden zuzufügen. Die Flagge verschwindet nicht und sämtliche Verbündete im Bereich erhalten einen SDN-WDS von 20 %. Wird man 20-mal getroffen, wird die Flagge erneut beschworen. Bei jeder Beschwörung einer Flagge werden die Cooldowns aller Fähigkeiten um 5 Sekunden verringert. Befindet sich Carlota auf dem Schlachtfeld, wird zudem, sobald die passive Fähigkeit eines verbündeten Clareths 20 Stapelungen erreicht, für 5 Sekunden Fähigkeitenblockade ausgelöst."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_UNIT_SKILL_DESC_KNIGHT_C_FLAG_PASSIVE_LV5"
L36_1 = "Innerhalb des Flaggenbereichs Absorption wirksamer Treffer für sich selbst +200 %. Gewährt sich selbst sowie verbündeten [#NKM_UNIT_KNIGHT_C_FLAG_PASSIVE_LV5#]-Einheiten Immunität gegen Betäubungstreffer von Spezialfähigkeiten oder niedriger."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_DP_KEYWORD_NAME_NKM_UNIT_KNIGHT_C_FLAG_PASSIVE_LV5"
L37_1 = "Ritter der Erlösung"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
