L10_1 = "SI_DP_KEYWORD_DESC_UNIT_DANMACHI_CA_AIS_SKILL1"
L11_1 = "ATK +30% and DMG RES Penetration +50% for 6 seconds (Cannot be canceled), recovers 0.6% of Max HP when hit in [Enhancement] state"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_UNIT_SKILL_DESC_DANMACHI_CA_AIS_PASSIVE_LV1"
L12_1 = "A basic attack in [#UNIT_DANMACHI_CA_AIS_SKILL1#] state becomes an enhanced attack, inflicting AoE damage in front. For each hit, enhanced attacks deal additional damage equal to 2% of the current target's HP (Bosses excluded). Becomes immune to Hitstun from Special or lower skills while casting an enhanced attack."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_UNIT_SKILL_DESC_DANMACHI_CA_AIS_SKILL_LV5"
L13_1 = "[Enhancement] duration +4 s"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_UNIT_SKILL_DESC_DREAM_C_WRITER_PASSIVE_LV1"
L14_1 = "Lädt bei einem Einsatz die Wutzählung aller Verbündeten mit einer Wut-Kennzeichnung 6-mal auf. Zusätzlich wird die Wutzählung der Verbündeten mit Wut-Kennzeichnung in Reichweite von 250 um den Einsatzpunkt 3-mal zusätzlich aufgeladen. Fallen die eigenen LP auf 30 % oder darunter, wird sie für einen Moment unverwundbar und das Ultimate-Cooldown wird um 30 Sekunden verringert."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_SKILL_DESC_DREAM_C_WRITER_HYPER_LV1"
L15_1 = "Beim Wirken erhalten alle Gegner im Radius von 500 um den Anwender für 15 Sekunden -30 % ATMP. Anschließend kehrt der Anwender zu seinem Einsatzpunkt zurück und stellt dabei 100 % seiner LP wieder her. Nach der Rückkehr an den Einsatzpunkt wird der Einsatzeffekt erneut ausgelöst."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_UNIT_SKILL_DESC_SHARKS_C_CLAW_PASSIVE_LV1"
L16_1 = "Nach jeweils 4 Standardangriffen wird ein verbesserter Angriff ausgelöst, der Betäubung verursacht. Der Schaden des verbesserten Angriffs steigt proportional zu den eigenen max. LP. Stellt 5 % der LP wieder her bei verbessertem Angriff (10 % bei Ultimate-Fähigkeiten)."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_ITEM_MISC_NAME_IMI_ITEM_MISC_SELFIE_FRAME_GAUNTLET_FENRIR_CA_HILDE_PR"
L17_1 = "Rahmen: Vergiss den Anteil nicht"
