L16_1 = {}
L17_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_GAUNTLET_FENRIR_CA_HILDE_PR"
L18_1 = "Ein Rahmen, der zeigt, wie sie sich auf ihre eigene Art als Casino-Händlerin behauptet hat, selbst ohne die festen Regeln zu kennen.\nIm Profil ausrüstbar, um die Stärke des Unternehmens zu beweisen."
