L25_1 = {}
L26_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80068_1"
L27_1 = "Gemeinsam mit deinen Gefährten unterstützt du Seo Yoon dabei, die C.O.s zu beseitigen.\nKaum ist die Mission abgeschlossen, sucht Seo Yoon dich auf."
L25_1[1] = L26_1
L25_1[2] = L27_1
