L28_1 = "Ah, ähm… wegen der Belohnung…"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80068_3"
L29_1 = "Ich habe es mir genau überlegt und denke, es ist richtig, Ihnen etwas zu geben, das Ihrer Erforschung am meisten nützt."
L27_1[1] = L28_1
L27_1[2] = L29_1
