L31_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80068_6"
L32_1 = "An ihrem Blick wird deutlich, dass dein Protest nicht gehört wird.\nSo entscheidest du dich, die Expedition gemeinsam mit Seo Yoon fortzusetzen."
L30_1[1] = L31_1
L30_1[2] = L32_1
