L32_1 = "SI_EXPLORE_EVENT_RESULTDESC2_80068_1"
L33_1 = "Du kümmerst dich nur um die besonders gefährlichen C.O.s für sie und machst dich dann wieder auf den Weg.\nSeo Yoon schaut enttäuscht, doch es lässt sich nicht ändern.\nAuftrag bleibt Auftrag, Erkundung bleibt Erkundung.\nWir brauchen nicht das Risiko anderer zu übernehmen."
L31_1[1] = L32_1
L31_1[2] = L33_1
