L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_PROLOGUE"
L3_1 = "Das Paradies erfüllt die Wünsche all seiner Bewohner."
L1_1[1] = L2_1
