L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_1"
L4_1 = "Dieser Groll wählte für das Mädchen bereitwillig den Wunsch, niemals zu erwachen."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_2"
L5_1 = "Eine Welt, in der der Tod bedeutungslos geworden ist. Eine Welt, in der Träume Wirklichkeit werden. Die verletzte Seele bleibt im Gehege des Paradieses eingeschlossen und versinkt in Frieden und Geborgenheit."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_3"
L6_1 = "Der Goldene Baum steht immer an seinem Platz. Selbst die Zeit verweilt dort. Wer in die Zukunft voranschreitet, ist nicht würdig, ihm zu begegnen."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_4"
L7_1 = "Je länger das Gummiband einer Schleuder ist, desto weiter fliegt der Stein, und je länger die Schnur eines Kreisels ist, desto länger dreht er sich. Mit einer Zeitmaschine verhält es sich nicht anders."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_5"
L8_1 = "Am Ende des Herbstes, einen Tag vor dem Winter, bleibt das Mädchen in der Zeit dieses Tages stehen, wird zu einem einsamen Goldenen Baum und hält mit ihrem eigenen Tod das Morgen auf."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_6"
L9_1 = "Ich habe dich in einer Samtschatulle verborgen, tief in einem Abgrund, den selbst Götter nicht erreichen können, und hoffte, dass wenigstens du makellos weiß bleibst."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_7"
L10_1 = "Das Recht, in die Zukunft zu gehen, wird nur denen gewährt, die den Mut haben, sich ihrer Vergangenheit zu stellen."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_DUNGEON_NAME_NKM_MAIN_BATTLE_EP15_1_1"
L11_1 = "Sonne und Mond"
