L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP15_1_1"
L12_1 = "Der Mut, sich der Vergangenheit zu stellen, ist keine Flucht in sie zurück, sondern der Mut, weiter in die Zukunft zu gehen."
